:root {
  --c50: #f4f7f7;
  --c100: #e3e9ea;
  --c200: #c9d6d8;
  --c300: #a4b8bc;
  --c400: #779299;
  --c500: #779299;
  --c600: #5a757c;
  --c700: #44545a;
  --c800: #3d484d;
  --c900: #363f43;
  --c950: #21282b;

  --ink-900: var(--c900);
  --ink-800: var(--c800);
  --ink-700: var(--c700);
  --ink-500: var(--c500);
  --sky-100: var(--c100);
  --sky-050: var(--c50);
  --line: var(--c200);
  --line-strong: var(--c300);
  --nav-from: var(--c500);
  --nav-to: var(--c500);
}

/* Caja Grande: alternar la misma grilla entre saldos pendientes e historial cerrado. */
.accounting-bigcash-view .bigcash-receivables-switch {
  display: inline-grid;
  grid-template-columns: repeat(2, minmax(0, auto));
  gap: 0.35rem;
  margin: 0.9rem 0 0.25rem;
  padding: 0.3rem;
  border: 1px solid #d9e3f1;
  border-radius: 0.8rem;
  background: #f3f7fc;
}

.accounting-bigcash-view .bigcash-receivables-switch button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  min-height: 2.45rem;
  padding: 0.55rem 0.85rem;
  border: 0;
  border-radius: 0.62rem;
  background: transparent;
  color: #52637b;
  font: inherit;
  font-size: 0.82rem;
  font-weight: 850;
  cursor: pointer;
}

.accounting-bigcash-view .bigcash-receivables-switch button.is-active {
  background: #123d78;
  color: #fff;
  box-shadow: 0 0.25rem 0.7rem rgba(18, 61, 120, 0.2);
}

.accounting-bigcash-view .bigcash-receivables-switch b {
  display: inline-grid;
  min-width: 1.55rem;
  height: 1.55rem;
  padding: 0 0.35rem;
  place-items: center;
  border-radius: 999px;
  background: #fff;
  color: #123d78;
  font-size: 0.72rem;
}

.accounting-bigcash-view .bigcash-finalized-receivable-row > td:last-child small {
  display: block;
  margin-top: 0.25rem;
  color: #708097;
}

@media (max-width: 700px) {
  .accounting-bigcash-view .bigcash-receivables-switch {
    width: 100%;
    grid-template-columns: minmax(0, 1fr);
  }
}

/* Disponibilidad v7: carga compacta, panorama de stock y contratos */
.app-content .workspace:has(.availability-view) {
  padding-top: 0.45rem !important;
}

.availability-view {
  gap: 0.5rem !important;
}

.availability-hero {
  padding-top: 0 !important;
  padding-bottom: 0.1rem !important;
}

.availability-products-section > header {
  min-height: 0 !important;
  margin-bottom: 0 !important;
  padding: 0.55rem 0.78rem !important;
}

.availability-loading-banner {
  min-height: 2rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  border: 1px solid #d8e5f4;
  border-radius: 0.62rem;
  background: #f5f9ff;
  padding: 0.42rem 0.68rem;
  color: #244a7b;
  font-size: 0.72rem;
  font-weight: 850;
}

.availability-loading-dot {
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 999px;
  background: #2f6fd0;
  box-shadow: 0 0 0 0 rgba(47, 111, 208, 0.35);
  animation: availability-loading-pulse 1.25s infinite;
}

@keyframes availability-loading-pulse {
  70% { box-shadow: 0 0 0 0.42rem rgba(47, 111, 208, 0); }
  100% { box-shadow: 0 0 0 0 rgba(47, 111, 208, 0); }
}

.availability-results-grid {
  min-width: 1320px !important;
}

.availability-results-grid th:nth-child(1),
.availability-results-grid td:nth-child(1) { width: 22% !important; }
.availability-results-grid th:nth-child(2),
.availability-results-grid td:nth-child(2) { width: 9% !important; }
.availability-results-grid th:nth-child(3),
.availability-results-grid td:nth-child(3) { width: 10% !important; }
.availability-results-grid th:nth-child(4),
.availability-results-grid td:nth-child(4) { width: 12% !important; }
.availability-results-grid th:nth-child(5),
.availability-results-grid td:nth-child(5) { width: 13% !important; }
.availability-results-grid th:nth-child(6),
.availability-results-grid td:nth-child(6) { width: 9% !important; text-align: center !important; }
.availability-results-grid th:nth-child(7),
.availability-results-grid td:nth-child(7) { width: 7% !important; text-align: center !important; }
.availability-results-grid th:nth-child(8),
.availability-results-grid td:nth-child(8) { width: 8% !important; text-align: center !important; }
.availability-results-grid th:nth-child(9),
.availability-results-grid td:nth-child(9) { width: 10% !important; text-align: center !important; }

.availability-result-stock,
.availability-result-available {
  display: grid;
  justify-items: center;
}

.availability-deferred-image,
.availability-deferred-image > img,
.availability-deferred-image > span {
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  object-fit: cover;
}

.availability-result-stock strong,
.availability-result-available strong {
  color: #102b59;
  font-size: 1rem;
  font-weight: 950;
}

.availability-result-available strong {
  color: #0f7a3c;
}

.availability-contracts-button {
  min-height: 2rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  border: 1px solid #f0b58f;
  border-radius: 0.58rem;
  background: #fff7f1;
  color: #cf4607;
  padding: 0.35rem 0.52rem;
  font: inherit;
  font-size: 0.68rem;
  font-weight: 900;
  cursor: pointer;
}

.availability-contracts-button b {
  min-width: 1.3rem;
  border-radius: 999px;
  background: #e9530a;
  color: #fff;
  padding: 0.12rem 0.3rem;
  font-size: 0.62rem;
}

.availability-contracts-button:disabled {
  border-color: #dde4ed;
  background: #f5f7fa;
  color: #8a96a8;
  cursor: default;
}

.availability-contracts-button:disabled b {
  background: #9aa6b6;
}

.availability-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 4000;
  display: grid;
  place-items: center;
  background: rgba(7, 20, 45, 0.58);
  padding: 1rem;
}

.availability-contracts-modal {
  width: min(1120px, calc(100vw - 2rem));
  max-height: min(82vh, 760px);
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
  border: 1px solid #dce4ef;
  border-radius: 1rem;
  background: #fff;
  box-shadow: 0 1.4rem 4rem rgba(5, 18, 42, 0.24);
}

.availability-contracts-modal > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  border-bottom: 1px solid #e3e8ef;
  background: #fff9f5;
  padding: 0.9rem 1rem;
}

.availability-contracts-modal > header span,
.availability-contracts-modal-list small {
  color: #758199;
  font-size: 0.62rem;
  font-weight: 900;
  text-transform: uppercase;
}

.availability-contracts-modal > header h3 {
  margin: 0.16rem 0 0;
  color: #102b59;
  font-size: 1.2rem;
}

.availability-contracts-modal > header p {
  margin: 0.2rem 0 0;
  color: #5f6f87;
  font-size: 0.76rem;
  font-weight: 750;
}

.availability-contracts-modal > header button {
  width: 2.2rem;
  height: 2.2rem;
  display: grid;
  place-items: center;
  border: 1px solid #dce3ed;
  border-radius: 0.58rem;
  background: #fff;
  color: #53627a;
  cursor: pointer;
}

.availability-contracts-modal > header button svg {
  width: 1rem;
  height: 1rem;
}

.availability-contracts-modal-list {
  overflow: auto;
  padding: 0.8rem;
}

.availability-contracts-modal-list article {
  display: grid;
  grid-template-columns: 0.75fr 1.2fr 0.9fr 1.3fr 0.45fr;
  gap: 0.8rem;
  align-items: center;
  border-bottom: 1px solid #e8edf3;
  padding: 0.72rem 0.65rem;
}

.availability-contracts-modal-list article:nth-child(even) {
  background: #f8fafd;
}

.availability-contracts-modal-list article > div {
  min-width: 0;
  display: grid;
  gap: 0.12rem;
}

.availability-contracts-modal-list article strong {
  color: #142d57;
  font-size: 0.78rem;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.availability-contracts-modal-list article span {
  color: #6c7890;
  font-size: 0.68rem;
  line-height: 1.2;
}

.availability-contracts-modal-code > strong {
  color: #d94a0b !important;
}

.availability-contracts-modal-qty {
  text-align: center;
}

.availability-contracts-modal-qty strong {
  font-size: 1.1rem !important;
}

.availability-contracts-empty {
  padding: 2rem;
  color: #728097;
  text-align: center;
}

@media (max-width: 768px) {
  .app-content .workspace:has(.availability-view) {
    padding-top: 0 !important;
  }

  .availability-results-grid {
    min-width: 0 !important;
  }

  .availability-results-grid tbody tr {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .availability-results-grid tbody td:nth-child(5),
  .availability-results-grid tbody td:nth-child(6) {
    grid-column: 1 / -1;
  }

  .availability-contracts-modal-list article {
    grid-template-columns: 1fr 1fr;
  }

  .availability-contracts-modal-list article > div:nth-child(4) {
    grid-column: 1 / -1;
  }
}

/* Caja Grande · rediseño final operativo */
.accounting-bigcash-view {
  width: min(100%, 1320px);
  margin-inline: auto;
  padding: 0 0.85rem 1.4rem;
  display: grid;
  gap: 1rem;
}

.accounting-bigcash-view .accounting-bigcash-head {
  align-items: center;
  padding: 0.15rem 0.1rem 0.1rem;
}

.accounting-bigcash-view .accounting-bigcash-head h2 {
  color: #061f49;
  font-size: clamp(2.05rem, 2.8vw, 2.65rem);
  font-weight: 950;
  letter-spacing: -0.045em;
}

.accounting-bigcash-view .accounting-bigcash-head p {
  color: #68758c;
  font-size: 0.94rem;
  font-weight: 650;
}

.accounting-bigcash-view .bigcash-kpi-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0.78rem;
}

.accounting-bigcash-view .bigcash-kpi-card,
.accounting-bigcash-view .bigcash-card {
  border: 1px solid rgba(226, 213, 205, 0.98);
  border-radius: 1.05rem;
  background: #fff;
  box-shadow: 0 1rem 2.2rem rgba(24, 34, 54, 0.06);
}

.accounting-bigcash-view .bigcash-kpi-card {
  min-height: 7.2rem;
  padding: 1rem;
}

.accounting-bigcash-view .bigcash-hero-icon {
  width: 2.85rem;
  height: 2.85rem;
  border-radius: 0.9rem;
}

.accounting-bigcash-view .bigcash-kpi-card h3 {
  font-size: clamp(1.42rem, 1.7vw, 1.75rem);
}

.accounting-bigcash-view .bigcash-command-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.92rem;
  align-items: stretch;
}

.accounting-bigcash-view .bigcash-command-card {
  min-height: 25rem;
  padding: 1.05rem;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 0.82rem;
  overflow: hidden;
}

.accounting-bigcash-view .bigcash-command-card > header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0.85rem;
  align-items: start;
  padding-bottom: 0.78rem;
  border-bottom: 1px solid rgba(11, 45, 99, 0.09);
}

.accounting-bigcash-view .bigcash-command-card > header > div > span:first-child {
  color: #ef4b0a;
  font-size: 0.68rem;
  font-weight: 950;
  letter-spacing: 0.055em;
  text-transform: uppercase;
}

.accounting-bigcash-view .bigcash-command-card > header h3 {
  margin: 0.15rem 0 0;
  display: flex;
  align-items: center;
  gap: 0.45rem;
  color: #09275b;
  font-size: 1.06rem;
  font-weight: 950;
}

.accounting-bigcash-view .bigcash-command-card > header p {
  margin-top: 0.22rem;
  color: #68758c;
  font-size: 0.78rem;
  font-weight: 650;
}

.accounting-bigcash-view .bigcash-command-card > header > strong {
  border-radius: 999px;
  padding: 0.45rem 0.72rem;
  background: #fff3ea;
  color: #dc4c05;
  font-size: 0.98rem;
  font-weight: 950;
  white-space: nowrap;
  box-shadow: inset 0 0 0 1px rgba(239, 75, 10, 0.14);
}

.accounting-bigcash-view .bigcash-command-card.guarantees > header > strong {
  background: #f5efff;
  color: #7138bd;
  box-shadow: inset 0 0 0 1px rgba(113, 56, 189, 0.16);
}

.accounting-bigcash-view .bigcash-command-list {
  display: grid;
  gap: 0.66rem;
  align-content: start;
  min-height: 0;
}

.accounting-bigcash-view .bigcash-action-row {
  position: relative;
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0.18rem 0.72rem;
  align-items: center;
  min-height: 4.9rem;
  padding: 0.78rem 0.85rem 0.78rem 1rem !important;
  border: 1px solid rgba(11, 45, 99, 0.1);
  border-radius: 0.92rem;
  background: #f8fbff;
  overflow: hidden;
}

.accounting-bigcash-view .bigcash-action-row::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 0.22rem;
  background: #ef4b0a;
}

.accounting-bigcash-view .bigcash-action-row.guarantee::before {
  background: #7c3aed;
}

.accounting-bigcash-view .bigcash-action-row.ready {
  background: #fffaf0;
}

.accounting-bigcash-view .bigcash-action-row.waiting {
  background: #f8fbff;
}

.accounting-bigcash-view .bigcash-action-row span,
.accounting-bigcash-view .bigcash-action-row small {
  grid-column: 1 / -1;
  color: #697790;
  font-size: 0.72rem;
  font-weight: 800;
}

.accounting-bigcash-view .bigcash-action-row strong {
  min-width: 0;
  color: #071f49;
  font-size: 0.91rem;
  font-weight: 950;
  line-height: 1.16;
}

.accounting-bigcash-view .bigcash-action-row b {
  color: #08275b;
  font-size: 0.9rem;
  font-weight: 950;
}

.accounting-bigcash-view .bigcash-action-row .accounting-inline-action {
  justify-self: end;
  min-height: 2rem;
  border-radius: 999px;
  padding-inline: 0.88rem;
}

.accounting-bigcash-view .bigcash-action-row .accounting-inline-action:disabled {
  cursor: not-allowed;
  border-color: #dce3ef;
  background: #f4f7fb;
  color: #8794a8;
  box-shadow: none;
}

.accounting-bigcash-view .section-link.blue {
  justify-self: center;
  margin-top: 0.1rem;
  font-weight: 950;
}

.accounting-bigcash-view .bigcash-operations-grid {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(18rem, 0.78fr);
  gap: 0.92rem;
  align-items: start;
}

.accounting-bigcash-view .bigcash-movements,
.accounting-bigcash-view .bigcash-summary-card,
.accounting-bigcash-view .transport-margin-card {
  padding: 1rem;
}

.accounting-bigcash-view .bigcash-movements > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.72rem;
}

.accounting-bigcash-view .bigcash-movements > header h3,
.accounting-bigcash-view .bigcash-summary-card h3,
.accounting-bigcash-view .transport-margin-card h3 {
  margin: 0;
  display: flex;
  align-items: center;
  gap: 0.45rem;
  color: #08275b;
  font-size: 1rem;
  font-weight: 950;
}

.accounting-bigcash-view .bigcash-movements > header p,
.accounting-bigcash-view .bigcash-summary-note {
  margin: 0.22rem 0 0;
  color: #68758c;
  font-size: 0.78rem;
  font-weight: 650;
}

.accounting-bigcash-view .bigcash-toolbar {
  display: grid;
  grid-template-columns: minmax(9rem, 0.7fr) minmax(8rem, 0.55fr) minmax(13rem, 0.9fr) minmax(14rem, 1.2fr);
  gap: 0.65rem;
  margin-bottom: 0.75rem;
}

.accounting-bigcash-view .bigcash-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  overflow: hidden;
  border: 1px solid rgba(11, 45, 99, 0.13);
  border-radius: 0.9rem;
}

.accounting-bigcash-view .bigcash-table thead th {
  background: #0b2d63;
  color: #fff;
  font-size: 0.72rem;
  letter-spacing: 0.025em;
}

.accounting-bigcash-view .bigcash-table tbody td {
  border-bottom: 1px solid rgba(11, 45, 99, 0.1);
  color: #10254f;
  font-size: 0.78rem;
}

.accounting-bigcash-view .bigcash-table tbody tr:last-child td {
  border-bottom: 0;
}

.accounting-bigcash-view .bigcash-insights {
  display: grid;
  gap: 0.92rem;
}

.accounting-bigcash-view .bigcash-summary-formula.cash-composition {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr) auto minmax(0, 1fr);
  gap: 0.6rem;
  align-items: center;
  border-radius: 0.92rem;
}

.accounting-bigcash-view .transport-margin-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.58rem;
}

.accounting-bigcash-view .bigcash-status-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 1.65rem;
  border-radius: 999px;
  padding: 0.18rem 0.56rem;
  font-size: 0.68rem;
  font-weight: 950;
}

.accounting-bigcash-view .bigcash-status-pill.ready {
  border: 1px solid #fed7aa;
  background: #fff7ed;
  color: #c2410c;
}

.accounting-bigcash-view .bigcash-status-pill.waiting {
  border: 1px solid #dbe3ef;
  background: #f5f7fb;
  color: #64748b;
}

@media (max-width: 1180px) {
  .accounting-bigcash-view .bigcash-kpi-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .accounting-bigcash-view .bigcash-command-grid,
  .accounting-bigcash-view .bigcash-operations-grid {
    grid-template-columns: 1fr;
  }

  .accounting-bigcash-view .bigcash-command-card {
    min-height: auto;
  }
}

@media (max-width: 768px) {
  .accounting-bigcash-view {
    padding-inline: 0.55rem;
  }

  .accounting-bigcash-view .accounting-bigcash-head,
  .accounting-bigcash-view .accounting-overview-actions,
  .accounting-bigcash-view .accounting-bigcash-action-group {
    width: 100%;
    display: grid;
    grid-template-columns: 1fr;
  }

  .accounting-bigcash-view .bigcash-kpi-grid,
  .accounting-bigcash-view .bigcash-toolbar,
  .accounting-bigcash-view .bigcash-summary-formula.cash-composition {
    grid-template-columns: 1fr;
  }
}

/* Asistencia grupal por responsable. */
.attendance-view .attendance-mode-panel {
  display: grid;
  gap: 0.45rem;
  padding: 0.8rem;
  border: 1px solid #dce4ef;
  border-radius: 0.85rem;
  background: #f8fafc;
}

.attendance-view .attendance-mode-label {
  color: #34415d;
  font-size: 0.72rem;
  font-weight: 900;
  text-transform: uppercase;
}

.attendance-view .attendance-mode-toggle {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.45rem;
}

.attendance-view .attendance-mode-toggle button {
  min-height: 2.7rem;
  border: 1px solid #dce3ed;
  border-radius: 0.7rem;
  background: #fff;
  color: #47536c;
  font-weight: 850;
  cursor: pointer;
}

.attendance-view .attendance-mode-toggle button.active {
  border-color: #f26c32;
  background: #fff2e9;
  color: #c83b00;
  box-shadow: 0 0 0 3px rgba(239, 75, 5, 0.09);
}

.attendance-view .attendance-mode-panel > small {
  color: #778198;
  font-size: 0.68rem;
  line-height: 1.35;
}

.attendance-view .attendance-responsible-panel {
  display: grid;
  gap: 0.75rem;
  padding: 0.85rem;
  border: 1px solid #bfd7f5;
  border-radius: 0.9rem;
  background: linear-gradient(145deg, #f5f9ff, #ffffff);
}

.attendance-view .attendance-responsible-panel > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.attendance-view .attendance-responsible-panel > header > span {
  min-width: 0;
  display: grid;
  gap: 0.12rem;
}

.attendance-view .attendance-responsible-panel > header strong {
  color: #17345f;
  font-size: 0.82rem;
}

.attendance-view .attendance-responsible-panel > header small {
  color: #71809a;
  font-size: 0.63rem;
}

.attendance-view .attendance-responsible-panel > header b {
  flex: 0 0 auto;
  border-radius: 999px;
  background: #e4efff;
  color: #1756a5;
  padding: 0.3rem 0.58rem;
  font-size: 0.62rem;
}

.attendance-view .attendance-participant-search {
  display: grid;
  gap: 0.3rem;
