  min-height: 1.55rem;
  align-items: center;
  border-radius: 999px;
  padding: 0.15rem 0.62rem;
  font-size: 0.72rem;
  font-weight: 950;
}

.attendance-type.entrada {
  color: #087443;
  background: #e6f7ee;
}

.attendance-type.salida {
  color: #c2410c;
  background: #fff0e7;
}

.attendance-thumb {
  width: 3.2rem;
  height: 3.2rem;
  object-fit: cover;
  border-radius: 0.55rem;
  border: 1px solid #dfe5ee;
}

.attendance-thumb-button {
  width: max-content;
  border: 0;
  border-radius: 0.68rem;
  background: transparent;
  padding: 0;
  cursor: zoom-in;
}

.attendance-thumb-button:hover .attendance-thumb,
.attendance-thumb-button:focus-visible .attendance-thumb {
  border-color: #f05a0a;
  box-shadow: 0 0 0 3px rgba(240, 90, 10, 0.14);
}

.attendance-photo-placeholder {
  min-height: 3.2rem;
  display: grid;
  place-items: center;
  border: 1px dashed #f0d8c8;
  border-radius: 0.55rem;
  background: #fff8f3;
  color: #9a3412;
  font-size: 0.72rem;
  font-weight: 900;
  text-align: center;
  padding: 0.45rem;
}

.attendance-photo-modal-backdrop {
