  inset: 0;
  z-index: 900;
  display: grid;
  place-items: center;
  padding: 1.2rem;
  background: rgba(11, 18, 32, 0.7);
  backdrop-filter: blur(7px);
}

.attendance-photo-modal {
  width: min(760px, 100%);
  max-height: min(86vh, 760px);
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 1rem;
  background: #ffffff;
  box-shadow: 0 2rem 5rem rgba(0, 0, 0, 0.34);
}

.attendance-photo-modal header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  border-bottom: 1px solid #edf0f5;
  padding: 0.85rem 1rem;
}

.attendance-photo-modal header span {
  color: #e94a00;
  font-size: 0.68rem;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.attendance-photo-modal header h3 {
  margin: 0.14rem 0 0;
  color: #102047;
  font-size: 1.05rem;
  line-height: 1.15;
}

.attendance-photo-modal header button {
  width: 2.25rem;
  height: 2.25rem;
  border: 1px solid #f0d8c8;
  border-radius: 0.68rem;
  background: #fff8f3;
  color: #d94706;
  font-size: 1.2rem;
  font-weight: 900;
  cursor: pointer;
}

.attendance-photo-modal img,
.attendance-photo-modal .attendance-photo-placeholder {
  width: 100%;
  height: 100%;
  max-height: calc(min(86vh, 760px) - 4.2rem);
}

.attendance-photo-modal img {
  object-fit: contain;
  background: #0b1220;
}

.attendance-photo-modal .attendance-photo-placeholder {
  border: 0;
  border-radius: 0;
  background: #0b1220;
  color: #ffffff;
  font-size: 0.95rem;
}

@media (max-width: 920px) {
  .attendance-hero,
  .attendance-layout {
    grid-template-columns: 1fr;
  }

  .attendance-hero {
    display: grid;
    align-items: start;
  }

  .attendance-kpis {
    grid-template-columns: 1fr;
  }

  .attendance-filters {
    grid-template-columns: 1fr 1fr;
  }

  .petty-main-grid,
  .petty-side,
  .petty-debts-card {
    grid-column: auto;
    grid-row: auto;
  }
}

html {
