  display: inline-flex;
  align-items: center;
  gap: 0.32rem;
  box-shadow: 0 10px 24px rgba(138, 56, 4, 0.08);
}

.presence-strip > strong {
  color: #7c3507;
  font-size: 0.7rem;
  font-weight: 950;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  padding: 0 0.18rem;
}

.presence-strip span {
  min-width: 8.7rem;
  height: 2.28rem;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--presence-color) 24%, #ffffff);
  background: #ffffff;
  color: #071343;
  display: grid;
  grid-template-columns: auto 1fr;
  column-gap: 0.38rem;
  align-items: center;
  padding: 0.22rem 0.58rem 0.22rem 0.22rem;
