  border: 2px solid #ffffff;
  background: var(--presence-color);
  color: #ffffff;
  display: grid;
  place-items: center;
  font-size: 0.62rem;
  font-weight: 950;
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--presence-color) 38%, transparent);
  font-style: normal;
  grid-row: span 2;
}

.presence-strip span.active {
  background: color-mix(in srgb, var(--presence-color) 8%, #ffffff);
  box-shadow: inset 3px 0 0 var(--presence-color), 0 0 0 2px color-mix(in srgb, var(--presence-color) 22%, transparent);
}

.presence-strip b,
.presence-strip em {
  display: block;
