}

.presence-strip b {
  font-size: 0.72rem;
  font-weight: 950;
}

.presence-strip em {
  color: #7b8299;
  font-size: 0.62rem;
  font-style: normal;
  font-weight: 800;
}

.presence-strip em small {
  display: inline;
