  font-size: inherit;
  font-weight: inherit;
  padding: 0;
}

.presence-strip em small + small::before {
  content: " · ";
  color: #b05a2c;
}

.presence-strip small {
  color: #7c4a00;
  font-size: 0.72rem;
  font-weight: 850;
