}

.system-database-copy p {
  color: var(--c700);
  font-size: 0.84rem;
  max-width: 720px;
}

.system-database-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.55rem;
}

.system-database-actions > button,
.system-database-actions > input,
.system-database-file {
  min-height: 42px;
}

.system-database-file {
  border: 1px dashed rgba(37, 99, 235, 0.34);
  border-radius: 0.68rem;
  background: #fff;
  color: var(--c700);
  font-size: 0.84rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0.4rem 0.65rem;
  cursor: pointer;
  overflow: hidden;
}

.system-database-file input {
  display: none;
}

.system-database-file span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.system-database-result {
  grid-column: 1 / -1;
  border-radius: 0.7rem;
  padding: 0.62rem 0.75rem;
  display: grid;
  gap: 0.16rem;
}

.system-database-result.success {
  border: 1px solid rgba(22, 163, 74, 0.24);
  background: #ecfdf5;
}

.system-database-result strong {
  color: #166534;
}

.system-database-result p {
  color: #246647;
  font-size: 0.82rem;
}

.system-reset-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 0.9rem;
  align-items: start;
}

.system-reset-modules,
.system-reset-impact {
  display: grid;
  gap: 0.85rem;
}

.system-reset-group {
  display: grid;
  gap: 0.55rem;
}

.system-reset-group h4,
.system-reset-impact h4 {
  margin: 0;
  color: var(--c900);
  font-size: 0.95rem;
}

.system-reset-module-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.62rem;
}

.system-reset-card {
  border: 1px solid rgba(164, 184, 188, 0.55);
  border-radius: 0.72rem;
  background: #fff;
  padding: 0.7rem;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.35rem 0.55rem;
  cursor: pointer;
}

.system-reset-card input {
  margin-top: 0.15rem;
}

.system-reset-card span {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.55rem;
}

.system-reset-card strong {
  color: var(--c900);
  font-size: 0.9rem;
}

.system-reset-card small {
  border-radius: 999px;
  background: #f2f5f6;
  color: var(--c700);
  font-size: 0.7rem;
  font-weight: 800;
  padding: 0.12rem 0.42rem;
}

.system-reset-card p,
.system-reset-card em {
  grid-column: 2;
  font-size: 0.78rem;
}

.system-reset-card em {
  color: #7c2d12;
  font-style: normal;
}

.system-reset-card.risk-alto,
.system-reset-card.risk-critico {
  border-color: rgba(223, 63, 5, 0.3);
}

.system-reset-card.risk-critico small {
  background: #fee2e2;
  color: #991b1b;
}

.system-reset-impact {
  border: 1px solid rgba(164, 184, 188, 0.55);
  border-radius: 0.78rem;
  background: #fff;
  padding: 0.8rem;
  position: sticky;
  top: 0.5rem;
}

.system-reset-summary {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.35rem 0.7rem;
  border-radius: 0.65rem;
  background: #f7fafb;
  padding: 0.65rem;
}

.system-reset-summary span {
  color: var(--c700);
  font-size: 0.8rem;
}

.system-reset-summary strong {
  color: var(--brand);
}

.system-reset-impact-list {
  display: grid;
  gap: 0.55rem;
  max-height: 360px;
  overflow: auto;
}

.system-reset-impact-list article {
  border-top: 1px solid rgba(164, 184, 188, 0.45);
  padding-top: 0.5rem;
  display: grid;
  gap: 0.25rem;
}

.system-reset-impact-list header {
  display: flex;
  justify-content: space-between;
  gap: 0.6rem;
  color: var(--c900);
}

.system-reset-impact-list p,
.system-reset-muted {
  font-size: 0.78rem;
  color: var(--c700);
}

.system-reset-confirm {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(220px, 0.36fr);
  gap: 0.75rem;
}

.system-reset-confirm textarea {
  resize: vertical;
  min-height: 64px;
}

.system-reset-result {
  border: 1px solid rgba(22, 163, 74, 0.25);
  border-radius: 0.72rem;
  background: #ecfdf5;
  padding: 0.7rem 0.8rem;
}

.system-reset-result strong {
  color: #166534;
}

.system-reset-result p {
  color: #246647;
  margin-top: 0.2rem;
}

@media (max-width: 920px) {
  .system-reset-layout,
  .system-reset-confirm {
    grid-template-columns: 1fr;
  }

  .system-reset-module-grid {
    grid-template-columns: 1fr;
  }

  .system-reset-impact {
    position: static;
  }

  .system-database-panel,
  .system-database-actions {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 1120px) {
  .brand-name {
    font-size: 1.65rem;
  }

  .inventory-panel {
    grid-template-columns: 1fr;
  }

  .inventory-ops-cards {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .inventory-ops-grid {
    grid-template-columns: 1fr;
  }

  .inventory-ops-recovery-head {
    flex-direction: column;
    align-items: stretch;
  }

  .inventory-ops-recovery-search {
    width: 100%;
  }

  .inventory-ops-recovery-gallery {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .caja-grid {
    grid-template-columns: 1fr;
  }

  .caja-history-filters {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .caja-history-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .recibos-grid {
    grid-template-columns: 1fr;
  }

  .categories-panel {
    grid-template-columns: 1fr;
  }

  .rental-split-form {
    grid-template-columns: 1fr;
  }

  .rental-main-grid {
    grid-template-columns: 1fr;
  }

  .rental-v2-left,
  .rental-v2-right {
    min-height: auto;
  }

  .rental-v2-toolbar {
    grid-template-columns: 1fr 1fr;
  }

  .stats-grid,
  .money-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .columns {
    grid-template-columns: 1fr;
  }

  .return-row {
    grid-template-columns: 1fr repeat(3, minmax(0, 1fr));
  }

  .rental-selected-row {
    grid-template-columns: 58px 1fr;
    align-items: start;
  }

  .rental-v2-selected-row {
    grid-template-columns: 60px 1fr;
    align-items: start;
  }

  .rental-qty-control,
  .rental-line-total,
  .rental-remove-button {
    grid-column: 2;
  }

  .rental-v2-qty,
  .rental-v2-line-total,
  .rental-v2-remove-btn {
    grid-column: 2;
  }

  .rental-line-total {
    text-align: left;
  }

  .rental-v2-line-total {
    text-align: left;
  }

  .return-v2-topbar {
    grid-template-columns: 1fr;
  }

  .return-v2-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .return-orders-header {
    flex-direction: column;
  }

  .return-orders-loan-btn {
    width: 100%;
  }
}

@media (max-width: 780px) {
  .topbar-inner,
  .shell {
    width: calc(100% - 1rem);
  }

  .topbar-inner {
    flex-direction: column;
    align-items: flex-start;
  }

  .brand-group {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.25rem;
  }

  .app-header {
    flex-direction: column;
  }

  .app-header-inventory {
    padding: 1.1rem 1rem;
  }

  .tab-list-inventory {
    padding: 0.7rem 1rem;
  }

  .workspace-inventory .panel {
    padding: 0.8rem;
  }

  .form-grid {
    grid-template-columns: 1fr;
  }

  .line-row,
  .return-row {
    grid-template-columns: 1fr;
  }

  .rental-items-header {
    grid-template-columns: 1fr;
  }

  .rental-v2-catalog-header {
    grid-template-columns: 1fr;
  }

  .rental-v2-form-grid {
    grid-template-columns: 1fr;
  }

  .rental-v2-gallery {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .rental-v2-toolbar {
    grid-template-columns: 1fr;
  }

  .recibos-filters {
    grid-template-columns: 1fr;
  }

  .recibo-kv-grid {
    grid-template-columns: 1fr;
  }

  .recibo-detail-list li {
    grid-template-columns: 1fr;
  }

  .caja-summary-grid {
    grid-template-columns: 1fr;
  }

  .caja-history-filters,
  .caja-history-stats {
    grid-template-columns: 1fr;
  }

  .caja-history-header {
    flex-direction: column;
  }

  .rental-v2-pager {
    justify-content: flex-start;
    flex-wrap: wrap;
  }

  .return-v2-gallery {
    grid-template-columns: 1fr;
  }

  .return-v2-item-head {
    grid-template-columns: 56px 1fr;
  }

  .return-v2-state {
    grid-column: 1 / -1;
    justify-self: start;
  }

  .return-v2-inputs {
    grid-template-columns: 1fr;
  }

  .return-v2-metrics {
    grid-template-columns: 1fr;
  }

  .return-orders-grid {
    grid-template-columns: 1fr;
    max-height: none;
  }

  .return-order-meta {
    grid-template-columns: 1fr;
  }

  .return-order-items li {
    grid-template-columns: 1fr;
  }

  .return-editor-grid {
    grid-template-columns: 1fr;
  }

  .return-editor-inputs {
    grid-template-columns: 1fr;
  }

  .stats-grid,
  .money-grid {
    grid-template-columns: 1fr;
  }

  .inventory-ops-cards {
    grid-template-columns: 1fr;
  }

  .inventory-ops-recovery-gallery {
    grid-template-columns: 1fr;
  }
}

/* Tema base inspirado en referencia compartida (azul corporativo + superficies claras) */
:root {
  --c50: #f8f8ff;
  --c100: #f0f2fb;
  --c200: #e4e8f6;
  --c300: #d2d9ef;
  --c400: #a0add5;
  --c500: #5e60ce;
  --c600: #4c4fd1;
  --c700: #20245c;
  --c800: #171a47;
  --c900: #111436;
  --c950: #0b0d25;

  --ink-900: #1f2345;
  --ink-800: #2d3560;
  --ink-700: #6b7395;
  --line: #e6e9f5;
  --line-strong: #ced4eb;
}

.app-frame {
  min-height: 100vh;
  background: linear-gradient(180deg, #f7f8fd, #f2f4fb);
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 30;
  background: rgba(247, 248, 253, 0.9);
  border-bottom: 1px solid #e4e8f5;
  backdrop-filter: blur(8px);
}

.topbar-inner {
  width: min(1440px, calc(100% - 2rem));
  margin: 0 auto;
  padding: 0.72rem 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

.top-search {
  min-width: min(560px, 100%);
  width: min(560px, 100%);
  border: 1px solid #dde3f4;
  border-radius: 0.7rem;
  background: #ffffff;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 0.55rem;
  padding: 0.15rem 0.4rem;
}

.top-search input {
  border: 0;
  background: transparent;
  padding: 0.45rem 0.2rem;
  color: var(--ink-900);
}

.top-search input:focus {
  outline: none;
  border: 0;
}

.top-search-icon {
  font-size: 0.74rem;
  font-weight: 700;
  color: #7981a7;
  padding-left: 0.2rem;
}

.top-search-shortcut {
  border: 1px solid #dbe2f5;
  border-radius: 0.48rem;
  color: #8289ac;
  font-size: 0.72rem;
  font-weight: 700;
  padding: 0.15rem 0.5rem;
  white-space: nowrap;
}

.top-actions {
  display: flex;
  align-items: center;
  gap: 0.45rem;
}

.mode-pill {
  border-radius: 999px;
  padding: 0.2rem 0.55rem;
  font-size: 0.72rem;
  font-weight: 700;
}

.mode-pill-web {
  background: #e8ecff;
  color: #4b50c7;
}

.top-icon {
  width: 2rem;
  height: 2rem;
  border-radius: 50%;
  border: 1px solid #d9deef;
  background: #ffffff;
  color: #4f57b5;
  font-size: 0.78rem;
  font-weight: 800;
}

.secret-reset-trigger {
  width: 1rem;
  height: 1rem;
  border-radius: 50%;
  border: 1px solid #dbe0f2;
  color: #dbe0f2;
  background: #ffffff;
  display: grid;
  place-items: center;
  padding: 0;
  font-size: 0.5rem;
}

.user-pill {
  border: 1px solid #dfe4f3;
  border-radius: 999px;
  background: #ffffff;
  color: var(--ink-900);
  padding: 0.24rem 0.68rem;
  display: grid;
  gap: 0.05rem;
}

.user-pill strong {
  font-size: 0.8rem;
  line-height: 1.15;
}

.user-pill span {
  color: #7b83a8;
  font-size: 0.68rem;
  line-height: 1.1;
}

.shell {
  width: min(1440px, calc(100% - 2rem));
  margin: 0.95rem auto 1.5rem;
}

.workspace-shell {
  display: grid;
  grid-template-columns: 265px minmax(0, 1fr);
  gap: 1rem;
  align-items: start;
}

.tab-list {
  position: sticky;
  top: 4.4rem;
  border: 1px solid #1f2364;
  border-radius: 1rem;
  background: linear-gradient(180deg, #171a4c, #10133d);
  padding: 0.75rem;
  display: grid;
  gap: 0.4rem;
  box-shadow: 0 16px 34px rgba(13, 18, 58, 0.34);
}

.tab-list-inventory {
  margin: 0;
}

.sidebar-brand {
  padding: 0.35rem 0.3rem 0.7rem;
  border-bottom: 1px solid rgba(177, 186, 240, 0.2);
  margin-bottom: 0.15rem;
}

.sidebar-brand-title {
  margin: 0;
  color: #f8f9ff;
  font-size: 1.45rem;
  font-weight: 700;
  letter-spacing: -0.015em;
}

.sidebar-brand-subtitle {
  color: #aeb6df;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.62rem;
  font-weight: 700;
}

.sidebar-section-title {
  margin: 0.32rem 0.3rem 0.15rem;
  color: #9ca5d3;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  font-size: 0.63rem;
  font-weight: 700;
}

.tab {
  border: 1px solid transparent;
  background: transparent;
  color: #c9d0f3;
  border-radius: 0.62rem;
  font-weight: 700;
  padding: 0.56rem 0.68rem;
  text-align: left;
  display: grid;
  gap: 0.12rem;
  transition: background-color 0.12s ease, transform 0.12s ease;
}

.tab:hover {
  background: rgba(98, 104, 213, 0.22);
  transform: translateY(-1px);
}

.tab-title {
  font-size: 0.84rem;
}

.tab-hint {
  font-size: 0.68rem;
  color: #8f98ca;
  font-weight: 600;
}

.tab.active {
  background: linear-gradient(135deg, #595be8, #4b4dd8);
  color: #ffffff;
}

.tab.active .tab-hint {
  color: #d9ddff;
}

.sidebar-help-card {
  margin-top: 0.45rem;
  border: 1px solid rgba(177, 186, 240, 0.24);
  border-radius: 0.8rem;
  background: rgba(255, 255, 255, 0.05);
  padding: 0.62rem;
  display: grid;
  gap: 0.22rem;
}

.sidebar-help-card p {
  margin: 0;
  color: #f0f2ff;
  font-size: 0.76rem;
  font-weight: 700;
}

.sidebar-help-card span {
  color: #b4bbe1;
  font-size: 0.68rem;
}

.sidebar-help-card button {
  margin-top: 0.3rem;
  border: 1px solid rgba(208, 214, 248, 0.45);
  border-radius: 0.55rem;
  background: #ffffff;
  color: #3239a4;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.42rem 0.55rem;
  cursor: pointer;
}

.workspace {
  border-radius: 1rem;
  border: 1px solid #e4e8f5;
  background: #f8f9ff;
  box-shadow: 0 10px 26px rgba(92, 101, 156, 0.08);
  padding: 0.92rem;
  display: grid;
  gap: 0.82rem;
}

.workspace-inventory {
  border: 1px solid #e4e8f5;
  background: #f8f9ff;
  box-shadow: 0 10px 26px rgba(92, 101, 156, 0.08);
  overflow: visible;
  gap: 0.82rem;
}

.app-header-modern {
  padding: 0.85rem 1.2rem;
  align-items: center;
  gap: 0.75rem;
  border-radius: 0.85rem;
  border: 1px solid #e4e8f5;
  background: #ffffff;
  box-shadow: 0 8px 20px rgba(98, 109, 173, 0.09);
}

.app-header-kicker {
  margin: 0;
  color: #5962aa;
  font-size: 0.72rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.app-header h1 {
  color: var(--ink-900);
  font-size: clamp(1.55rem, 2vw, 2rem);
  line-height: 1.08;
}

.app-header p {
  color: #666f95;
}

.header-refresh-button {
  min-width: 128px;
}

.panel {
  gap: 0.8rem;
}

.stat-card,
.money-card,
.list-card,
.form-card,
.table-card,
.rental-v2-card,
.return-v2-card,
.return-orders-card,
.recibos-detail-card,
.recibos-filter-card {
  border-radius: 0.8rem;
  border: 1px solid #e6eaf7;
  background: #ffffff;
  box-shadow: 0 5px 16px rgba(103, 112, 170, 0.07);
}

.stats-grid .stat-card:nth-child(1) {
  background: #f3efff;
}

.stats-grid .stat-card:nth-child(2) {
  background: #eaf7f1;
}

.stats-grid .stat-card:nth-child(3) {
  background: #edf3ff;
}

.stats-grid .stat-card:nth-child(4) {
  background: #fff3e9;
}

.money-grid .money-card:nth-child(1) {
  background: #f1f5ff;
}

.money-grid .money-card:nth-child(2) {
  background: #eefaf4;
}

.money-grid .money-card:nth-child(3) {
  background: #fff5ee;
}

.money-grid .money-card:nth-child(4) {
  background: #f5f1ff;
}

.card-badge {
  border-color: #d5dbf2;
  background: #ffffff;
  color: #5d66a4;
}

.primary-button {
  border: 1px solid #474dd2;
  background: linear-gradient(140deg, #5b5fea, #4a4dd6);
  color: #ffffff;
}

.ghost-button {
  border: 1px solid #d9def1;
  background: #ffffff;
  color: #5760a2;
}

.danger-button {
  border: 1px solid #9e5164;
  background: linear-gradient(180deg, #c46478, #b55769);
  color: #ffffff;
}

.table-card th {
  color: #7079a8;
}

.table-card td {
  color: #343d66;
}

input,
select,
textarea {
  border-color: #d8def1;
  background: #ffffff;
}

input:focus,
select:focus,
textarea:focus {
  outline: 2px solid rgba(91, 95, 234, 0.2);
  border-color: #6568e6;
}

@media (max-width: 1260px) {
  .workspace-shell {
    grid-template-columns: 1fr;
  }

  .tab-list {
    position: static;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    background: #171a4c;
  }

  .sidebar-brand,
  .sidebar-section-title,
  .sidebar-help-card {
    grid-column: 1 / -1;
  }
}

@media (max-width: 900px) {
  .topbar-inner,
  .shell {
    width: calc(100% - 1rem);
  }

  .topbar-inner {
    flex-direction: column;
    align-items: stretch;
  }

  .top-search {
    width: 100%;
    min-width: 100%;
  }

  .top-actions {
    justify-content: flex-end;
  }

  .tab-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* Ajuste fino para parecerse al mock de referencia */
.tab-list {
  border-radius: 0;
  min-height: calc(100vh - 6.2rem);
}

.workspace {
  border-radius: 0.8rem;
}

.user-pill {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  padding-right: 0.55rem;
}

.user-avatar {
  width: 1.65rem;
  height: 1.65rem;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 0.62rem;
  font-weight: 800;
  color: #ffffff;
  background: linear-gradient(135deg, #4f56d6, #7076ea);
}

.user-meta {
  display: grid;
  line-height: 1.1;
