  height: 0.68rem;
  border-radius: 50%;
  margin-top: 0.2rem;
  border: 2px solid;
  background: #ffffff;
  z-index: 1;
}

.agenda-marker::before {
  content: '';
  position: absolute;
  width: 0.2rem;
  height: 0.2rem;
  border-radius: 50%;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: currentColor;
}

.agenda-marker::after {
  content: '';
  position: absolute;
  left: 50%;
  top: calc(100% + 0.18rem);
  bottom: -1.5rem;
  transform: translateX(-50%);
  width: 1px;
  background: #dfe4ef;
}

