@media (max-width: 1280px) {
  .orders-kpi-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 980px) {
  .orders-header,
  .orders-footer {
    flex-direction: column;
    align-items: flex-start;
  }

  .orders-header-actions {
    width: 100%;
    flex-wrap: wrap;
  }

  .orders-kpi-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .orders-toolbar {
    grid-template-columns: 1fr;
  }

  .orders-export-btn {
    justify-self: start;
  }

  .orders-wizard-steps {
    grid-template-columns: 1fr;
  }

  .orders-modal-body {
    grid-template-columns: 1fr;
  }

  .orders-form-grid,
  .orders-money-grid {
    grid-template-columns: 1fr;
  }

  .orders-items-toolbar,
  .orders-product-row,
  .orders-logistics-mode {
    grid-template-columns: 1fr;
  }

  .orders-product-thumb {
    display: none;
  }

  .orders-catalog-gallery {
    grid-template-columns: 1fr;
  }

  .orders-selected-row {
    grid-template-columns: 1fr;
  }

  .orders-modal-foot,
  .orders-modal-foot-right {
    flex-wrap: wrap;
    justify-content: flex-start;
  }
}

