  font-weight: 700;
}

.settings-side-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.44rem;
}

.settings-side-grid label:first-child,
.settings-side-grid label:last-child {
  grid-column: 1 / -1;
}

.settings-logo-zone {
  display: grid;
  gap: 0.36rem;
}

.settings-logo-label {
  color: #6d769d;
  font-size: 0.74rem;
  font-weight: 700;
}

.settings-logo-row {
  display: grid;
  grid-template-columns: 160px minmax(0, 1fr);
  gap: 0.42rem;
}

.settings-logo-preview {
  border: 1px solid #3f46b9;
  background: #1f2b74;
  color: #f3f5ff;
  border-radius: 0.5rem;
  padding: 0.45rem;
  display: flex;
  align-items: center;
  gap: 0.32rem;
}

.settings-logo-preview strong {
  font-size: 1.82rem;
  line-height: 1;
  font-family: 'Georgia', 'Times New Roman', serif;
}

.settings-logo-mark {
  width: 1.55rem;
  height: 1.55rem;
  display: grid;
  place-items: center;
}

.settings-logo-mark svg {
  width: 1.55rem;
  height: 0.95rem;
  display: block;
}

.settings-upload-button {
  border: 1px dashed #cfd6ef;
  border-radius: 0.5rem;
  background: #f9fbff;
  color: #5d6796;
  display: grid;
  place-items: center;
  gap: 0.08rem;
  padding: 0.38rem;
  cursor: pointer;
}

.settings-upload-icon {
  width: 1.16rem;
  height: 1.16rem;
  color: #5c62dd;
}

.settings-upload-icon svg {
  width: 1.16rem;
  height: 1.16rem;
  display: block;
}

.settings-upload-button span {
  font-size: 0.76rem;
  font-weight: 700;
}

.settings-upload-button small {
  color: #8a92b6;
  font-size: 0.66rem;
}

.settings-remove-logo {
  justify-self: start;
  border: 0;
  background: transparent;
  color: #5b60dc;
  font-size: 0.72rem;
  font-weight: 700;
  padding: 0;
  cursor: pointer;
}

.settings-currency select {
  max-width: 300px;
}

.settings-form-grid-compact {
  margin-top: 0.5rem;
}

.settings-check-row {
  display: inline-flex;
  align-items: center;
  gap: 0.42rem;
  color: #2f3968;
  font-size: 0.82rem;
  font-weight: 600;
}

.settings-check-row input {
  width: auto;
  margin: 0;
}

.settings-help {
  margin: -0.22rem 0 0.52rem;
  color: #7c84a8;
  font-size: 0.76rem;
}

.settings-numbering-wrap {
  border: 1px solid #e8ecf8;
  border-radius: 0.52rem;
  overflow: hidden;
}

.settings-numbering-table {
  width: 100%;
  border-collapse: collapse;
}

.settings-numbering-table th,
.settings-numbering-table td {
  border-bottom: 1px solid #eef1fa;
  padding: 0.38rem 0.4rem;
  text-align: left;
  white-space: nowrap;
}

.settings-numbering-table th {
  background: #f8faff;
  color: #7a82aa;
  font-size: 0.7rem;
  font-weight: 700;
}

.settings-numbering-table td {
  color: #3b4574;
  font-size: 0.75rem;
}

.settings-numbering-table input {
  padding: 0.35rem 0.45rem;
  border-radius: 0.42rem;
  font-size: 0.74rem;
}

@media (max-width: 1320px) {
  .settings-kpi-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .settings-layout {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 980px) {
  .settings-tabs-row {
    flex-direction: column;
    align-items: stretch;
  }

  .settings-save-button {
    width: 100%;
  }

  .settings-form-grid,
  .settings-side-grid {
    grid-template-columns: 1fr;
  }

  .settings-logo-row {
    grid-template-columns: 1fr;
  }

  .settings-currency select {
    max-width: none;
  }
}

@media (max-width: 760px) {
  .settings-kpi-grid {
    grid-template-columns: 1fr;
  }

  .settings-header h2 {
    font-size: 1.7rem;
  }
}

/* Sidebar: anclar ayuda al fondo */
@media (min-width: 1181px) {
  .tab-list {
    display: flex;
    flex-direction: column;
    align-items: stretch;
  }

  .tab-list .sidebar-help-card {
    margin-top: auto;
  }
}

@media (max-width: 1180px) {
  .tab-list .sidebar-help-card {
    margin-top: 0.28rem;
  }
}

/* --------------------------------------------------------------------------
   Copetin UI polish: escala visual comun para todas las vistas operativas.
   Esta capa final corrige diferencias acumuladas de tamano, espaciado y peso
   visual sin tocar la logica funcional de cada modulo.
   -------------------------------------------------------------------------- */
:root {
  --ui-bg: #f5f7fc;
  --ui-surface: #ffffff;
  --ui-surface-soft: #f9fbff;
  --ui-border: #dfe6f4;
  --ui-border-soft: #edf1fa;
  --ui-text: #17214d;
  --ui-heading: #121b46;
  --ui-muted: #69749f;
  --ui-subtle: #8790b5;
  --ui-primary: #5258df;
  --ui-primary-strong: #393fc8;
  --ui-primary-soft: #eef0ff;
  --ui-danger: #c94d5f;
  --ui-success: #19865a;
  --ui-warning: #b86b28;
  --ui-radius-sm: 0.58rem;
  --ui-radius-md: 0.78rem;
  --ui-radius-lg: 1rem;
  --ui-shadow-card: 0 10px 26px rgba(31, 42, 91, 0.055);
  --ui-shadow-float: 0 24px 70px rgba(24, 34, 74, 0.28);
  --ui-font-xs: 0.68rem;
  --ui-font-sm: 0.74rem;
  --ui-font-md: 0.82rem;
  --ui-font-lg: 0.94rem;
  --ui-font-title: clamp(1.75rem, 2.05vw, 2.18rem);
  --ui-font-metric: clamp(2rem, 2.35vw, 2.44rem);
}

body {
  background: var(--ui-bg);
  color: var(--ui-text);
}

.app-content {
  background:
    radial-gradient(circle at top right, rgba(82, 88, 223, 0.055), transparent 34rem),
    linear-gradient(180deg, #f7f9ff 0%, #f2f5fb 100%);
}

