.top-icon {
  position: relative;
  width: 2rem;
  height: 2rem;
  border: 0;
  background: transparent;
  color: #4d5875;
  font-size: 0;
}

.top-icon::before {
  content: '';
  width: 1.18rem;
  height: 1.18rem;
  display: block;
  margin: auto;
  background: currentColor;
  mask: url("data:image/svg+xml,%3Csvg viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M12 22a2.4 2.4 0 0 0 2.32-1.8H9.68A2.4 2.4 0 0 0 12 22Zm7-6.2V11a7 7 0 0 0-5-6.7V3a2 2 0 0 0-4 0v1.3A7 7 0 0 0 5 11v4.8L3.6 18a1 1 0 0 0 .85 1.52h15.1A1 1 0 0 0 20.4 18L19 15.8Z'/%3E%3C/svg%3E") center / contain no-repeat;
}

.top-icon::after {
  content: '3';
  position: absolute;
  top: 0.05rem;
  right: 0.08rem;
  width: 0.95rem;
  height: 0.95rem;
  border-radius: 999px;
  background: var(--ref-primary);
