/* Autenticacion y usuarios operativos */
.login-shell {
  min-height: 100vh;
  position: relative;
  isolation: isolate;
  display: grid;
  place-items: center;
  overflow: hidden;
  background: #fff7f1;
  padding: clamp(1.2rem, 4vw, 4rem);
}

.login-shell::before,
.login-shell::after {
  content: "";
  position: absolute;
  z-index: -2;
  border: 52px solid rgba(235, 100, 29, 0.13);
  border-radius: 50%;
  pointer-events: none;
}

.login-shell::before {
  width: 31rem;
  height: 31rem;
  left: -7rem;
  top: -14rem;
}

.login-shell::after {
  width: 35rem;
  height: 35rem;
  right: -12rem;
  bottom: -18rem;
}

.login-orbit {
  position: absolute;
  z-index: -1;
  pointer-events: none;
  border: 1px solid rgba(226, 73, 0, 0.1);
  border-radius: 50%;
}

.login-orbit-top {
  width: 46rem;
  height: 46rem;
  left: -11rem;
  top: -23rem;
}

.login-orbit-bottom {
  width: 42rem;
  height: 42rem;
  right: -17rem;
  bottom: -23rem;
}

.login-card {
  width: min(1180px, 100%);
  min-height: 620px;
  border: 1px solid rgba(255, 255, 255, 0.72);
  border-radius: 1.35rem;
  background: #ffffff;
  box-shadow: 0 34px 110px rgba(75, 46, 31, 0.19);
  display: grid;
  grid-template-columns: minmax(420px, 0.9fr) minmax(420px, 1fr);
  overflow: hidden;
}

.login-showcase {
  position: relative;
  min-height: 620px;
  overflow: hidden;
  background: #e94a00;
  color: #ffffff;
}

.login-showcase-bg {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(0deg, rgba(222, 71, 0, 0.76), rgba(222, 71, 0, 0.82)),
    linear-gradient(135deg, rgba(255, 255, 255, 0.14), transparent 36%),
    image-set(
      url('/imagenes/login.optimized.jpg') type("image/jpeg"),
      url('/imagenes/login.png') type("image/png")
    ) center / cover no-repeat;
}

.login-showcase-bg::before,
.login-showcase-bg::after {
  content: "";
  position: absolute;
  inset: auto;
