}

.personnel-status.extra {
  color: #1d5fbf;
  background: #e8f1ff;
  border-color: #cfe0ff;
}

.personnel-status.observado,
.personnel-status.pendiente,
.personnel-status.vacation {
  color: #a15b07;
  background: #fff3d8;
  border-color: #f5db9e;
}

.personnel-status.incompleto,
.personnel-status.inactive,
.personnel-status.suspended,
.personnel-status.rechazado {
