  height: 2rem;
  flex: 0 0 2rem;
  border-radius: 999px;
  display: grid;
  place-items: center;
  overflow: hidden;
  border: 1px solid #e4ddf7;
  background: #f4f0ff;
  color: #6354dc;
}

.personnel-avatar.green {
  border-color: #cdebdc;
  background: #e8f8ef;
  color: #20825d;
}

.personnel-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.personnel-avatar svg {
  width: 1.12rem;
  height: 1.12rem;
}

.ghost-button.tiny {
  min-height: 1.85rem;
  padding: 0.22rem 0.5rem;
  border-radius: 0.55rem;
  font-size: 0.72rem;
}

.link-button.danger {
  border: 0;
  background: transparent;
  color: #c2412d;
  font: inherit;
  font-size: 0.75rem;
  font-weight: 800;
  cursor: pointer;
  padding: 0.18rem 0.24rem;
}

.link-button.danger:hover,
.link-button.danger:focus-visible {
  color: #9f2a1f;
  outline: none;
}

.personnel-modal {
  width: min(1040px, calc(100vw - 2rem));
  max-height: calc(100vh - 2rem);
  overflow: auto;
}

.personnel-incident-modal {
  width: min(760px, calc(100vw - 2rem));
}

.personnel-form-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.64rem;
  padding: 0.9rem;
}

.personnel-form-grid.compact {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.personnel-form-grid label {
  display: grid;
  gap: 0.24rem;
  color: #24345f;
  font-size: 0.75rem;
  font-weight: 800;
}

.personnel-photo-field {
  grid-row: span 2;
  display: grid;
  align-content: start;
  justify-items: center;
  gap: 0.52rem;
  border: 1px dashed #e9cbb8;
  border-radius: 0.74rem;
  background: #fff8f3;
  padding: 0.68rem;
}

.personnel-photo-preview {
  width: 6.5rem;
  height: 6.5rem;
  border-radius: 999px;
  overflow: hidden;
  display: grid;
  place-items: center;
  border: 2px solid #ffffff;
  background: #f3efe9;
  color: #d94d00;
  box-shadow: 0 10px 24px rgba(117, 59, 24, 0.14);
}

.personnel-photo-preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.personnel-photo-preview svg {
  width: 2.45rem;
  height: 2.45rem;
}

.personnel-photo-button {
  display: inline-flex !important;
  min-height: 2rem;
  align-items: center;
  justify-content: center;
  border: 1px solid #f0b691;
  border-radius: 0.58rem;
  background: #fff;
  color: #c74400 !important;
  cursor: pointer;
  padding: 0.36rem 0.62rem;
}

.personnel-form-grid input,
.personnel-form-grid select,
.personnel-form-grid textarea {
  width: 100%;
  border: 1px solid #dbe3f3;
  border-radius: 0.58rem;
  background: #fff;
  color: #12204a;
  font: inherit;
  font-size: 0.86rem;
  min-height: 2.45rem;
  padding: 0.52rem 0.62rem;
}

.personnel-form-grid input:disabled {
  background: #f6f7fb;
  color: #7a849d;
  cursor: default;
}

.personnel-form-grid textarea {
  min-height: 5.2rem;
  resize: vertical;
}

.personnel-form-grid :is(input, select, textarea):focus {
  border-color: #ea580c;
  outline: 3px solid rgba(234, 88, 12, 0.12);
}

.personnel-form-grid .span-2 {
  grid-column: span 2;
}

.personnel-days-field {
  border: 1px solid #dbe3f3;
  border-radius: 0.68rem;
  padding: 0.58rem;
  margin: 0;
}

.personnel-days-field legend {
  padding: 0 0.28rem;
  color: #24345f;
  font-size: 0.75rem;
  font-weight: 800;
}

.personnel-days-field > div {
  display: flex;
  gap: 0.38rem;
  flex-wrap: wrap;
}

.personnel-days-field label {
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  min-width: 3.1rem;
  min-height: 2rem;
  border: 1px solid #dbe3f3;
  border-radius: 999px;
  background: #ffffff;
  color: #58658a;
  cursor: pointer;
  padding: 0 0.54rem;
}

.personnel-days-field label.selected {
  border-color: #f0a070;
  background: #fff1e8;
  color: #d94d00;
}

.personnel-days-field input {
  position: absolute;
  width: 1px;
  height: 1px;
  min-height: 0;
  opacity: 0;
  pointer-events: none;
}

@media (max-width: 1160px) {
  .personnel-kpi-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .personnel-form-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 740px) {
  .personnel-kpi-grid,
  .personnel-form-grid,
  .personnel-form-grid.compact {
    grid-template-columns: 1fr;
  }

  .personnel-form-grid .span-2 {
    grid-column: auto;
  }

  .personnel-import-preview {
    align-items: stretch;
    flex-direction: column;
  }
}

@media (max-width: 980px) {
  .login-card {
    grid-template-columns: 1fr;
    width: min(640px, 100%);
    min-height: auto;
  }

  .login-showcase {
    min-height: 430px;
  }

  .login-showcase-content {
    padding: 1.7rem;
  }

  .login-copy {
    max-width: 30rem;
  }

  .login-form {
    padding: 2rem;
  }

  .login-secure-note {
    margin-top: 1rem;
  }
}

@media (max-width: 768px) {
  html,
  body,
  #root {
    max-width: 100vw;
    overflow-x: hidden;
  }

  body {
    width: 100%;
  }

  .login-shell {
    min-height: 100svh;
    width: 100%;
    place-items: start center;
    overflow-x: hidden;
    overflow-y: auto;
    padding: 1rem;
  }

  .login-shell::before,
  .login-shell::after,
  .login-orbit {
    display: none;
  }

  .login-card {
    width: 100%;
    max-width: 30rem;
    min-height: auto;
    grid-template-columns: 1fr;
    border-radius: 1rem;
  }

  .login-showcase {
    min-height: auto;
    max-height: none;
    overflow: hidden;
  }

  .login-showcase-bg {
    opacity: 0.96;
    background:
      linear-gradient(0deg, rgba(222, 71, 0, 0.76), rgba(222, 71, 0, 0.82)),
      linear-gradient(135deg, rgba(255, 255, 255, 0.14), transparent 36%),
      image-set(
        url('/imagenes/login.mobile.jpg') type("image/jpeg"),
        url('/imagenes/login.png') type("image/png")
      ) center / cover no-repeat;
  }

  .login-showcase-content {
    min-height: auto;
    padding: 1.25rem;
    display: block;
  }

  .login-brand {
    justify-content: center;
    gap: 0.72rem;
    text-align: left;
  }

  .login-brand-mark {
    width: 2.7rem;
    height: 2.7rem;
  }

  .login-brand h1 {
    font-size: 2.35rem;
  }

  .login-brand p {
    margin-top: 0.38rem;
    font-size: 0.78rem;
  }

  .login-copy,
  .login-service-grid {
    display: none;
  }

  .login-service-tile {
    min-height: auto;
  }

  .login-form {
    width: 100%;
    min-width: 0;
    padding: 1.35rem 1rem 1.25rem;
    align-content: start;
    gap: 1.15rem;
  }

  .login-form-head {
    text-align: center;
  }

  .login-form h2,
  .login-form-head h2 {
    font-size: 1.72rem;
  }

  .login-form p,
  .login-form-head p {
    font-size: 0.92rem;
  }

  .login-divider {
    gap: 0.7rem;
    margin-top: 0.72rem;
  }

  .login-fields {
    gap: 0.95rem;
  }

  .login-input-shell {
    min-height: 3.34rem;
  }

  .login-submit {
    min-height: 3.34rem;
  }

  .login-secure-note {
    margin-top: 0.3rem;
  }

  .user-editor-grid {
    grid-template-columns: 1fr;
  }

  .user-access-options {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .login-shell {
    padding: 0.85rem;
  }

  .login-card {
    max-width: 100%;
    border-radius: 0.92rem;
  }

  .login-showcase-content {
    padding: 1.05rem 0.95rem;
  }

  .login-brand-mark {
    width: 2.35rem;
    height: 2.35rem;
  }

  .login-brand h1 {
    font-size: 2rem;
  }

  .login-brand p {
    font-size: 0.72rem;
  }

  .login-form {
    padding: 1.12rem 0.9rem 1rem;
  }

  .login-form h2,
  .login-form-head h2 {
    font-size: 1.5rem;
  }

  .login-form p,
  .login-form-head p {
    font-size: 0.84rem;
  }

  .login-input-shell {
    gap: 0.55rem;
    padding: 0 0.7rem;
  }

  .login-input-shell input {
    font-size: 0.92rem;
  }

  .login-secure-note {
    justify-self: stretch;
    justify-content: center;
  }
}

/* Ordenes: tablero comercial-operativo redisenado. */
.orders-workflow-tabs {
  border: 0 !important;
  background: transparent !important;
  padding: 0 !important;
}

.orders-workflow-tabs button,
.orders-workflow-tabs button.active {
  border-radius: 0.76rem !important;
}

.orders-workflow-tabs button {
  background: #fbfcff !important;
  border: 1px solid #e8ecf8 !important;
  color: #36406f !important;
}

.orders-workflow-tabs button:hover,
.orders-workflow-tabs button:focus-visible {
  border-color: #f0b38f !important;
  background: #ffffff !important;
}

.orders-workflow-tabs button.active {
  border-color: #ef9b6c !important;
  background: linear-gradient(180deg, #fff7f1 0%, #ffffff 100%) !important;
  color: #24346a !important;
}

.orders-workflow-tabs button.active .orders-workflow-count {
  background: #e84a00 !important;
