/* Wizard comercial: disponibilidad visible y layout mas respirable. */
.orders-wizard-modal {
  width: min(1280px, calc(100vw - 2rem));
  max-height: calc(100vh - 1.4rem);
  overflow: hidden;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto auto;
}

.orders-wizard-modal.is-items-step {
  width: min(1450px, calc(100vw - 1rem));
}

.orders-wizard-modal.is-items-step .orders-wizard-body {
  grid-template-columns: minmax(0, 1fr) minmax(330px, 360px);
}

.orders-wizard-modal .orders-modal-head {
  padding: 1.02rem 1.08rem 0.92rem;
  background: linear-gradient(180deg, #ffffff 0%, #fffaf6 100%);
}

.orders-wizard-modal .orders-modal-head h3 {
  font-size: 1.72rem;
}

.orders-wizard-steps {
  padding: 0.74rem 1.08rem;
  background: #ffffff;
}

.orders-wizard-step {
  min-height: 3.35rem;
  padding: 0.48rem 0.56rem;
  border-color: #e8edf8;
  background: #fbfcff;
}

.orders-wizard-step.active {
  background: #fff4eb;
  border-color: #efaa80;
  box-shadow: inset 0 0 0 1px rgba(232, 74, 0, 0.08);
}

.orders-wizard-body {
  min-height: 0;
  grid-template-columns: minmax(0, 1fr) minmax(360px, 420px);
  gap: 0.9rem;
  padding: 0.9rem 1.08rem;
  overflow: auto;
  background: #fffdfb;
}

.orders-wizard-main,
.orders-wizard-side {
  align-self: start;
}

.orders-wizard-main {
  gap: 0.68rem;
}

.orders-wizard-side {
  position: sticky;
  top: 0;
}

.orders-items-toolbar {
  grid-template-columns: minmax(260px, 1.4fr) minmax(170px, 0.8fr) minmax(170px, 0.8fr);
  gap: 0.55rem;
}

.orders-search-feedback {
  border: 1px solid #cddcf6;
  border-radius: 0.72rem;
  background: #f6f9ff;
  padding: 0.58rem 0.68rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.7rem;
}

.orders-search-feedback > div {
  min-width: 0;
  display: grid;
  gap: 0.12rem;
}

.orders-search-feedback strong {
  color: #17366f;
  font-size: 0.82rem;
}

.orders-search-feedback span {
  color: #65739b;
  font-size: 0.72rem;
  font-weight: 700;
}

.orders-search-feedback .ghost-button {
  flex: 0 0 auto;
  min-height: 2.05rem;
}

.orders-quick-item-panel {
  border: 1px solid #d9e3f3;
  border-radius: 0.86rem;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(247, 250, 255, 0.96)),
    repeating-linear-gradient(0deg, transparent, transparent 23px, rgba(74, 95, 150, 0.06) 24px),
    repeating-linear-gradient(90deg, transparent, transparent 23px, rgba(74, 95, 150, 0.06) 24px);
  padding: 0.72rem;
  display: grid;
  gap: 0.62rem;
}

.orders-quick-item-panel.is-collapsed {
  padding: 0.52rem 0.68rem;
  background: #f8faff;
  border-style: dashed;
}

.orders-quick-item-panel header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
}

.orders-quick-item-panel header > div {
  display: grid;
  gap: 0.12rem;
}

.orders-quick-item-panel strong {
  color: #0b1f4f;
  font-size: 0.86rem;
}

.orders-quick-item-panel span {
  color: #66739b;
  font-size: 0.74rem;
  font-weight: 700;
}

.orders-quick-item-grid {
  display: grid;
  grid-template-columns: minmax(150px, 0.85fr) minmax(190px, 1.1fr) repeat(3, minmax(120px, 0.7fr));
  gap: 0.52rem;
}

.orders-quick-item-grid label {
  color: #5a3150;
  font-size: 0.72rem;
  font-weight: 850;
  display: grid;
  gap: 0.25rem;
}

.orders-quick-item-grid input {
  min-height: 2.2rem;
  border: 1px solid #d8deef;
  border-radius: 0.62rem;
  background: rgba(255, 255, 255, 0.92);
  padding: 0 0.68rem;
  color: #0b163f;
  font-weight: 750;
}

.orders-quick-item-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding-top: 0.58rem;
  border-top: 1px solid #e3e8f4;
}

.orders-quick-item-actions span {
  max-width: 42rem;
}

.orders-quick-item-actions .primary-button {
  flex: 0 0 auto;
}

.orders-availability-strip {
  display: grid;
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.45fr) minmax(0, 0.9fr);
  gap: 0.58rem;
}

.orders-availability-strip article {
  border: 1px solid #ead8c9;
  border-radius: 0.72rem;
  background: linear-gradient(180deg, #ffffff 0%, #fff8f2 100%);
  padding: 0.72rem 0.78rem;
  display: grid;
  gap: 0.18rem;
}

.orders-availability-strip span {
  color: #9a5a29;
  font-size: 0.68rem;
  font-weight: 850;
  text-transform: uppercase;
}

.orders-availability-strip strong {
  color: #1f2a58;
  font-size: 0.92rem;
  line-height: 1.2;
}

.orders-availability-strip small {
  color: #69739c;
  font-size: 0.72rem;
  font-weight: 700;
}

.orders-availability-strip article.success {
  border-color: #c7e6d5;
  background: linear-gradient(180deg, #ffffff 0%, #f2fbf6 100%);
}

.orders-availability-strip article.success span,
.orders-availability-strip article.success strong {
  color: #176f4d;
}

.orders-availability-strip article.danger {
  border-color: #ffc4b8;
  background: linear-gradient(180deg, #ffffff 0%, #fff3f0 100%);
}

.orders-availability-strip article.danger span,
.orders-availability-strip article.danger strong {
  color: #b42318;
}

.orders-availability-strip article.returns {
  border-color: #d7e3fb;
  background: linear-gradient(180deg, #ffffff 0%, #f6f9ff 100%);
}

.orders-availability-strip article.returns span,
.orders-availability-strip article.returns strong {
  color: #274c96;
}

.orders-return-mini-list {
  display: grid;
  gap: 0.1rem;
}

.orders-return-mini-list small {
  color: #52608e;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.orders-products-head {
  padding: 0 0.08rem;
  font-size: 0.74rem;
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  align-items: center;
  color: #64709b;
  font-weight: 700;
}

.orders-product-list {
  max-height: clamp(18rem, 38vh, 26rem);
  gap: 0.52rem;
  padding: 0.52rem;
  border-radius: 0.8rem;
  background: #fffaf6;
}

.orders-catalog-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.75rem;
  padding: 0.66rem 0.72rem;
  border: 1px dashed #e8d5c6;
  border-radius: 0.78rem;
  background: #fffaf6;
  color: #69739c;
  font-size: 0.74rem;
  font-weight: 700;
}

.orders-catalog-actions .ghost-button {
  flex: 0 0 auto;
  min-height: 2.2rem;
}

.orders-product-row {
  min-height: 5.6rem;
  grid-template-columns: 3.8rem minmax(0, 1fr) minmax(84px, auto) 3.4rem 5.7rem;
  align-items: center;
  gap: 0.7rem;
  padding: 0.66rem 0.72rem;
  border: 1px solid #ead8c9;
  border-radius: 0.72rem;
  background: #ffffff;
  box-shadow: 0 0.55rem 1.2rem rgba(80, 49, 24, 0.05);
}

.orders-product-row:last-child {
  border-bottom: 1px solid #ead8c9;
}

.orders-product-row.is-provisional {
  border-color: #b9d2ff;
  background: linear-gradient(180deg, #ffffff 0%, #f6f9ff 100%);
}

.orders-product-thumb {
  width: 3.3rem;
  height: 3.3rem;
  border-radius: 0.62rem;
}

.orders-product-info {
  display: grid;
  grid-template-columns: minmax(0, 0.72fr) minmax(250px, 1fr);
  grid-template-rows: auto auto;
  column-gap: 0.7rem;
  row-gap: 0.16rem;
  align-items: center;
}

.orders-product-info strong {
  grid-column: 1;
  grid-row: 1;
  font-size: 0.88rem;
  align-self: end;
}

.orders-product-info > span {
  grid-column: 1;
  grid-row: 2;
  align-self: start;
  margin: 0;
  color: #7a658f;
  font-size: 0.7rem;
  font-weight: 700;
}

.orders-availability-metrics {
  grid-column: 2;
  grid-row: 1 / span 2;
  align-self: center;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.38rem;
  width: 100%;
  max-width: 460px;
}

.orders-availability-metrics.is-provisional {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.orders-availability-metrics > span {
  min-height: 2.38rem;
  border: 1px solid #e5d7cb;
  border-radius: 0.58rem;
  background: #fffaf6;
  padding: 0.32rem 0.44rem;
  display: grid;
  gap: 0.04rem;
  align-content: center;
}

.orders-availability-metrics small {
  color: #7e87ad;
  font-size: 0.58rem;
  font-weight: 850;
  text-transform: uppercase;
}

.orders-availability-metrics strong {
  color: #223063;
  font-size: 1rem;
  line-height: 1;
}

.orders-availability-metrics.is-provisional strong {
  font-size: 0.78rem;
}

.orders-availability-metrics .primary {
  border-color: #efaa80;
  background: #fff3ea;
}

.orders-availability-metrics .primary small,
.orders-availability-metrics .primary strong {
  color: #c43a00;
}

.orders-availability-metrics .positive {
  border-color: #c7e6d5;
  background: #f2fbf6;
}

.orders-availability-metrics .positive small,
.orders-availability-metrics .positive strong {
  color: #176f4d;
}

.orders-availability-metrics .warning {
  border-color: #f1ddb9;
  background: #fff8e8;
}

.orders-availability-metrics .warning small,
.orders-availability-metrics .warning strong {
  color: #9a6518;
}

.orders-product-price {
  font-size: 0.82rem;
}

.orders-product-row .primary-button {
  min-height: 2.36rem;
  border-radius: 0.62rem;
  font-size: 0.74rem;
}

.orders-selected-list {
  border-radius: 0.8rem;
}

.orders-selected-section {
  border: 1px solid #ece2da;
  border-radius: 0.8rem;
  background: #ffffff;
  overflow: hidden;
}

.orders-selected-section .orders-selected-head {
  position: static;
  border-bottom: 1px solid #f0e1d5;
  padding: 0.62rem 0.68rem;
  background: #fffaf6;
}

.orders-selected-section .orders-selected-list {
  border: 0;
  border-radius: 0;
  background: #ffffff;
}

.orders-selected-editor {
  max-height: 340px;
}

.orders-selected-row {
  grid-template-columns: minmax(0, 1fr) minmax(168px, 190px) 92px auto auto;
  gap: 0.54rem;
  padding: 0.56rem;
  border-radius: 0.68rem;
}

.orders-selected-row strong {
  font-size: 0.8rem;
}

.orders-item-detail-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.28rem;
  margin-top: 0.34rem;
}

.orders-item-detail-chips span {
  min-height: 1.55rem;
  border: 1px solid #dce6f8;
  border-radius: 0.52rem;
  background: #f7faff;
  padding: 0.22rem 0.46rem;
  color: #203064;
  font-size: 0.68rem;
  font-weight: 850;
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
}

.orders-item-detail-chips small {
  color: #7b87af;
  font-size: 0.58rem;
  font-weight: 900;
  text-transform: uppercase;
}

.orders-line-field {
  gap: 0.22rem;
}

.orders-line-field > .orders-selected-availability + .orders-available-note:not(.is-warning) {
  display: none;
}

.orders-selected-availability {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.32rem;
}

.orders-selected-availability span {
  border: 1px solid #dbe8de;
  border-radius: 0.5rem;
  background: #f5fbf7;
  padding: 0.3rem 0.36rem;
  display: grid;
  gap: 0.02rem;
}

.orders-selected-availability small {
  color: #61735f;
  font-size: 0.54rem;
  text-transform: uppercase;
}

.orders-selected-availability strong {
  color: #176f4d;
  font-size: 0.84rem;
}

.orders-selected-availability.is-error span {
  border-color: #ffc4b8;
  background: #fff3f0;
}

.orders-selected-availability.is-error strong {
  color: #b42318;
}

@media (max-width: 1100px) {
  .orders-wizard-body {
    grid-template-columns: 1fr;
  }

  .orders-wizard-side {
    position: static;
  }

  .orders-availability-strip,
  .orders-quick-item-grid,
  .orders-items-toolbar {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
  .orders-quick-item-panel header,
  .orders-quick-item-actions,
  .orders-search-feedback {
    align-items: stretch;
    flex-direction: column;
  }

  .orders-quick-item-panel header .ghost-button,
  .orders-quick-item-actions .primary-button,
  .orders-search-feedback .ghost-button {
    width: 100%;
  }

  .orders-products-head,
  .orders-catalog-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .orders-product-row,
  .orders-selected-row {
    grid-template-columns: 1fr;
  }

  .orders-product-info {
    grid-template-columns: 1fr;
    grid-template-rows: auto;
  }

  .orders-product-info strong,
  .orders-product-info > span,
  .orders-availability-metrics {
    grid-column: 1;
    grid-row: auto;
  }

  .orders-availability-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    max-width: none;
  }
}

/* Ajuste final: tablero comercial simetrico y consistente con el sistema. */
.orders-view {
  gap: 1rem;
}

.orders-header {
  align-items: flex-end;
  gap: 1rem;
  padding-inline: 0.08rem;
}

.orders-header > div:first-child {
  max-width: 58rem;
}

.orders-header p {
  max-width: 54rem;
}

.orders-header-actions {
  margin-left: auto;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 0.56rem;
}

.orders-header-actions .orders-new-btn {
  min-width: 11.25rem;
  justify-content: center;
}

.orders-kpi-grid,
.orders-kpi-grid.is-two-up {
  width: 100%;
  max-width: none;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: stretch;
}

.orders-kpi-card {
  min-height: 126px;
  border-radius: 0.9rem;
  padding: 0.9rem 1rem 0.84rem;
  gap: 0.28rem;
}

.orders-kpi-card button {
  margin-top: auto;
}

.orders-table-card {
  border-radius: 0.92rem;
  padding: 1rem;
  gap: 0.9rem;
}

.orders-board-head {
  align-items: center;
  gap: 1rem;
}

.orders-board-head p {
  max-width: 58rem;
}

.orders-board-count {
  min-width: 4.6rem;
}

.orders-view-switch.orders-workflow-tabs {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.64rem;
}

.orders-workflow-tabs button {
  min-height: 4.25rem;
  padding: 0.82rem 0.92rem;
}

.orders-filter-panel {
  border-radius: 0.84rem;
  padding: 0.66rem;
}

.orders-toolbar {
  grid-template-columns: minmax(340px, 1fr) auto auto auto;
  gap: 0.52rem;
}

.orders-search,
.orders-select,
.orders-filter-btn,
.orders-range-btn {
  min-height: 2.55rem;
}

.orders-search input {
  font-size: 0.9rem;
}

.orders-export-btn {
  justify-self: end;
}

.orders-status-tabs {
  gap: 0.44rem;
}

.orders-status-tabs button {
  min-height: 2.1rem;
  padding-inline: 0.72rem;
}

.orders-table-wrap {
  border-radius: 0.84rem;
}

.orders-table th,
.orders-table td {
  padding: 0.7rem 0.65rem;
  vertical-align: middle;
}

.orders-empty-state {
  min-height: 11rem;
  border-radius: 0.84rem;
}

@media (max-width: 1200px) {
  .orders-toolbar {
    grid-template-columns: 1fr 1fr auto;
  }

  .orders-search {
    grid-column: 1 / -1;
  }
}

@media (max-width: 900px) {
  .orders-header {
    align-items: flex-start;
  }

  .orders-header-actions {
    width: 100%;
    justify-content: flex-start;
  }

  .orders-header-actions .orders-new-btn {
    min-width: 0;
    flex: 1 1 12rem;
  }

  .orders-kpi-grid,
  .orders-kpi-grid.is-two-up {
    grid-template-columns: 1fr;
  }

  .orders-view-switch.orders-workflow-tabs {
    grid-template-columns: 1fr;
  }
}

/* Vista Contabilidad */
