@keyframes updateMascotHello {
  0%, 100% { transform: rotate(0deg) translateY(0); }
  45% { transform: rotate(-2deg) translateY(-0.12rem); }
  65% { transform: rotate(2deg) translateY(0); }
}

@keyframes updateMascotHelloMini {
  0%, 100% { transform: scale(0.58) rotate(0deg) translateY(0); }
  45% { transform: scale(0.58) rotate(-2deg) translateY(-0.12rem); }
  65% { transform: scale(0.58) rotate(2deg) translateY(0); }
}

@keyframes updateMascotWave {
  0%, 100% { transform: rotate(-10deg); }
  50% { transform: rotate(17deg); }
