/* Catalogo publico para clientes */
.public-catalog-page {
  min-height: 100vh;
  padding: 1.25rem clamp(1rem, 3vw, 2.5rem) 2.5rem;
  background:
    radial-gradient(circle at top left, rgba(239, 90, 24, 0.14), transparent 28rem),
    linear-gradient(180deg, #fffaf6 0%, #f4f7fb 48%, #ffffff 100%);
  color: #061a3d;
}

.public-catalog-hero {
  min-height: clamp(15rem, 28vw, 24rem);
  border: 1px solid rgba(239, 90, 24, 0.28);
  border-radius: 0.75rem;
  background:
    linear-gradient(90deg, rgba(7, 10, 15, 0.92), rgba(7, 10, 15, 0.62) 48%, rgba(7, 10, 15, 0.1)),
    url('/imagenes/catalogo-web-hero.png') center / cover no-repeat;
  box-shadow: 0 1.25rem 3rem rgba(14, 24, 40, 0.18);
  display: flex;
  align-items: center;
  overflow: hidden;
}

.public-catalog-hero-copy {
  width: min(38rem, 92%);
  padding: clamp(1.25rem, 4vw, 3.5rem);
}

.public-catalog-hero-copy span,
.public-catalog-card-area {
  color: #ff6b16;
  font-size: 0.74rem;
  font-weight: 950;
  text-transform: uppercase;
}

.public-catalog-hero-copy h1 {
  margin: 0.45rem 0 0.65rem;
  color: #ffffff;
  font-size: clamp(2rem, 4.8vw, 4.25rem);
  line-height: 0.98;
}

.public-catalog-hero-copy p {
  max-width: 31rem;
  margin: 0;
  color: rgba(255, 255, 255, 0.82);
  font-size: clamp(0.95rem, 1.5vw, 1.12rem);
  line-height: 1.55;
}

.public-catalog-toolbar {
  position: sticky;
  top: 0;
  z-index: 4;
  margin: 1rem 0;
  padding: 0.8rem;
  border: 1px solid #dde6f2;
  border-radius: 0.75rem;
  background: rgba(255, 255, 255, 0.94);
  backdrop-filter: blur(16px);
  box-shadow: 0 0.75rem 2rem rgba(15, 23, 42, 0.08);
  display: grid;
  grid-template-columns: minmax(18rem, 1fr) minmax(10rem, 13rem) minmax(12rem, 16rem);
  gap: 0.65rem;
  align-items: end;
}

.public-catalog-toolbar label {
  display: grid;
  gap: 0.3rem;
  color: #64748b;
  font-size: 0.72rem;
  font-weight: 900;
  text-transform: uppercase;
}

.public-catalog-toolbar input,
.public-catalog-toolbar select {
  width: 100%;
  height: 2.85rem;
  border: 1px solid #dbe4f0;
  border-radius: 0.55rem;
  background: #ffffff;
  color: #0b1f44;
  font: inherit;
  font-weight: 800;
  padding: 0 0.85rem;
}

.public-catalog-more button {
  height: 2.85rem;
  border: 0;
  border-radius: 0.55rem;
  background: #e65300;
  color: #ffffff;
  font: inherit;
  font-weight: 950;
  padding: 0 1rem;
  cursor: pointer;
}

.public-catalog-summary {
  margin: 0 0 1rem;
  padding: 0.85rem 1rem;
  border: 1px solid #e4ebf4;
  border-radius: 0.75rem;
  background: #ffffff;
  display: flex;
  align-items: center;
  gap: 0.55rem;
  flex-wrap: wrap;
}

.public-catalog-summary strong {
  color: #e65300;
  font-size: 1.45rem;
  line-height: 1;
}

.public-catalog-summary span {
  font-weight: 950;
}

.public-catalog-summary em {
  margin-left: auto;
  color: #65738b;
  font-style: normal;
  font-size: 0.9rem;
}

.public-catalog-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(16rem, 1fr));
  gap: 1rem;
}

.public-catalog-card {
  min-width: 0;
  border: 1px solid #e4d8ce;
  border-radius: 0.65rem;
  background: #ffffff;
  overflow: hidden;
  box-shadow: 0 0.75rem 2rem rgba(15, 23, 42, 0.08);
}

.public-catalog-card-image {
  height: 15rem;
  padding: 0.85rem;
  border-bottom: 1px solid #eadfd5;
  background: #ffffff;
  display: grid;
  place-items: center;
}

.public-catalog-card-image img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
}

.public-catalog-card-placeholder {
  width: 100%;
  height: 100%;
  border: 1px dashed #eadfd5;
  border-radius: 0.5rem;
  color: #e65300;
  display: grid;
  place-items: center;
  font-size: 0.82rem;
  font-weight: 950;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.public-catalog-card-body {
  padding: 0.95rem;
  display: grid;
  gap: 0.42rem;
}

.public-catalog-card h2 {
  min-height: 2.6rem;
  margin: 0;
  color: #061a3d;
  font-size: 1.05rem;
  line-height: 1.2;
}

.public-catalog-card p {
  min-height: 1.2rem;
  margin: 0;
  color: #64748b;
  font-size: 0.86rem;
  line-height: 1.35;
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.public-catalog-card-meta {
  margin-top: 0.35rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.public-catalog-card-meta span {
  border-radius: 999px;
  background: #f1f5f9;
  color: #0b1f44;
  font-weight: 950;
  padding: 0.38rem 0.7rem;
}

.public-catalog-card-meta small {
  color: #7b8797;
  font-weight: 850;
}

.public-catalog-state,
.public-catalog-more {
  min-height: 8rem;
  border: 1px dashed #dbe4f0;
  border-radius: 0.75rem;
  background: rgba(255, 255, 255, 0.8);
  color: #64748b;
  display: grid;
  place-items: center;
  text-align: center;
  font-weight: 900;
}

.public-catalog-more {
  min-height: auto;
  margin-top: 1rem;
  padding: 1rem;
}

.public-catalog-state--error {
  border-color: #fecaca;
  background: #fff1f2;
  color: #be123c;
}

@media (max-width: 900px) {
  .public-catalog-toolbar {
    position: static;
    grid-template-columns: 1fr;
  }

  .public-catalog-summary em {
    width: 100%;
    margin-left: 0;
  }
}

@media (max-width: 560px) {
  .public-catalog-page {
    padding-inline: 0.75rem;
  }

  .public-catalog-card-image {
    height: 13rem;
  }
}

@media print {
  .public-catalog-toolbar,
  .public-catalog-more {
    display: none !important;
  }

  .public-catalog-page {
    background: #ffffff !important;
    padding: 0;
  }

  .public-catalog-hero {
    min-height: 9rem;
    box-shadow: none;
    break-after: avoid;
  }

  .public-catalog-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 0.55rem;
  }

  .public-catalog-card {
    box-shadow: none;
    break-inside: avoid;
  }
}


/* Contratos y ordenes anulados: se conservan como trazabilidad, pero quedan
   visualmente fuera de la operacion activa. */
.orders-view .orders-contracts-table tbody tr.contract-anulado td,
.orders-view .orders-table tbody tr.cancelled td {
  background: #dff4fb !important;
  border-color: #b8e3f2 !important;
  color: #4f7180 !important;
}

.orders-view .orders-contracts-table tbody tr.contract-anulado td:not(:last-child),
.orders-view .orders-table tbody tr.cancelled td:not(:last-child) {
  text-decoration: line-through;
  text-decoration-thickness: 1.5px;
  text-decoration-color: rgba(55, 119, 145, 0.72);
}

.orders-view .orders-contracts-table tbody tr.contract-anulado td:last-child,
.orders-view .orders-table tbody tr.cancelled td:last-child,
.orders-view .orders-contracts-table tbody tr.contract-anulado button,
.orders-view .orders-table tbody tr.cancelled button {
  text-decoration: none;
}


/* Usuarios: mostrar u ocultar la nueva contraseña */
.user-editor-modal .user-password-field {
  position: relative;
  display: block;
  width: 100%;
}

.user-editor-modal .user-password-field input {
  width: 100%;
  padding-right: 3rem;
}

.user-editor-modal .user-password-toggle {
  position: absolute;
  top: 50%;
  right: 0.42rem;
  width: 2.2rem;
  height: 2.2rem;
  padding: 0;
  transform: translateY(-50%);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 0.7rem;
  background: transparent;
  color: #6b7280;
  cursor: pointer;
  transition: background 0.16s ease, color 0.16s ease;
}

.user-editor-modal .user-password-toggle:hover {
  background: #fff1e8;
  color: #e84b05;
}

.user-editor-modal .user-password-toggle:focus-visible {
  outline: 2px solid rgba(232, 75, 5, 0.35);
  outline-offset: 1px;
}

.user-editor-modal .user-password-toggle svg {
  width: 1.18rem;
  height: 1.18rem;
}


/* Wizard de contratos: componentes de combo comprimibles */
.orders-combo-option-group {
  padding: 0;
  overflow: hidden;
}

.orders-combo-option-group > header {
  display: block;
}

.orders-combo-group-toggle {
  width: 100%;
  min-height: 4.25rem;
  border: 0;
  background: transparent;
  padding: 0.72rem;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto 1.7rem;
  gap: 0.72rem;
  align-items: center;
  text-align: left;
  cursor: pointer;
}

.orders-combo-group-toggle:hover {
  background: #fffaf6;
}

.orders-combo-group-toggle:focus-visible {
  outline: 2px solid rgba(239, 90, 24, 0.35);
  outline-offset: -2px;
}

.orders-combo-group-copy {
  min-width: 0;
  display: grid;
  gap: 0.15rem;
}

.orders-combo-group-copy > strong {
  color: #172b4d;
  font-size: 0.78rem;
}

.orders-combo-group-copy > span {
  color: #758199;
  font-size: 0.58rem;
}

.orders-combo-group-copy > small {
  min-width: 0;
  margin-top: 0.12rem;
  color: #e65313;
  font-size: 0.56rem;
  font-weight: 850;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.orders-combo-group-toggle .orders-combo-group-summary {
  min-width: 8.6rem;
}

.orders-combo-group-chevron {
  width: 1.25rem;
  height: 1.25rem;
  color: #667085;
  transition: transform 0.18s ease, color 0.18s ease;
}

.orders-combo-option-group.expanded .orders-combo-group-chevron {
  transform: rotate(90deg);
  color: #e65313;
}

.orders-combo-group-content {
  padding: 0 0.7rem 0.7rem;
  display: grid;
  gap: 0.58rem;
  border-top: 1px solid #edf0f5;
}

.orders-combo-group-content[hidden] {
  display: none;
}

.orders-combo-option-group.collapsed {
  box-shadow: 0 0.28rem 0.9rem rgba(15, 23, 42, 0.035);
}

@media (max-width: 768px) {
  .orders-combo-group-toggle {
    grid-template-columns: minmax(0, 1fr) 1.45rem;
    gap: 0.5rem;
    padding: 0.68rem;
  }

  .orders-combo-group-toggle .orders-combo-group-summary {
    grid-column: 1 / -1;
    grid-row: 2;
    min-width: 0;
    justify-items: start;
    grid-template-columns: auto auto;
    align-items: center;
    gap: 0.35rem;
  }

  .orders-combo-group-chevron {
    grid-column: 2;
    grid-row: 1;
    justify-self: end;
  }
}
/* Contabilidad 2026: jerarquia compacta, coherente con el flujo de Ordenes */
.accounting-redesign {
  --accounting-ink: #10254f;
  --accounting-muted: #64748b;
  --accounting-line: #dce5f2;
  --accounting-surface: #ffffff;
  --accounting-soft: #f6f8fc;
  --accounting-blue: #2563eb;
  --accounting-green: #059669;
  --accounting-orange: #e65300;
  --accounting-violet: #7c3aed;
  background: var(--accounting-soft);
  border: 1px solid #e5eaf2;
  border-radius: 20px;
  color: var(--accounting-ink);
  padding: clamp(16px, 2vw, 26px);
}

.accounting-redesign :is(.accounting-bigcash-head, .accounting-overview-head) {
  align-items: flex-start;
  background: var(--accounting-surface);
  border: 1px solid var(--accounting-line);
  border-radius: 16px;
  box-shadow: 0 10px 30px rgba(16, 37, 79, 0.06);
  margin-bottom: 16px;
  padding: 18px 20px;
}

.accounting-redesign :is(.accounting-bigcash-head, .accounting-overview-head) h2 {
  color: var(--accounting-ink);
  font-size: clamp(1.45rem, 2vw, 2rem);
  letter-spacing: -0.035em;
  margin: 0 0 4px;
}

.accounting-redesign :is(.accounting-bigcash-head, .accounting-overview-head) p {
  color: var(--accounting-muted);
  margin: 0;
}

.accounting-source-badge {
  align-items: center;
  background: #eff6ff;
  border: 1px solid #cfe0ff;
  border-radius: 999px;
  color: #315f9f;
  display: inline-flex;
  font-size: 0.72rem;
  font-weight: 800;
  gap: 7px;
  margin-top: 10px;
  padding: 5px 9px;
}

.accounting-source-badge i {
  background: #16a34a;
  border: 2px solid #dcfce7;
  border-radius: 50%;
  box-shadow: 0 0 0 2px rgba(22, 163, 74, 0.12);
