  width: 7px;
}

.accounting-redesign .accounting-overview-actions {
  align-items: center;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.accounting-redesign .accounting-date-control,
.accounting-redesign .accounting-overview-actions input[type="date"] {
  background: #fff;
  border-color: var(--accounting-line);
  border-radius: 10px;
  min-height: 42px;
}

.accounting-redesign .accounting-core-kpis,
.accounting-redesign .bigcash-kpi-grid {
  display: grid;
  gap: 12px;
