  transform: translateY(-1px);
}

.accounting-redesign .bigcash-kpi-content {
  align-items: flex-start;
}

.accounting-redesign .bigcash-kpi-card h3 {
  font-size: clamp(1.35rem, 2vw, 1.85rem);
  letter-spacing: -0.04em;
  margin: 7px 0 5px;
