.montage-product-picker-head span { color: #7a879a; font-size: .67rem; }
.montage-product-picker-head button {
  border: 0;
  background: transparent;
  color: #e65300;
  font-weight: 900;
  cursor: pointer;
}

.montage-product-picker > input {
  width: 100%;
  height: 2.45rem;
  border: 1px solid #dfe7f0;
  border-radius: .5rem;
  padding: 0 .7rem;
  color: #132743;
  font: inherit;
  font-size: .78rem;
}

.montage-product-strip {
  max-height: 19rem;
  overflow: auto;
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: .45rem;
  padding-right: .15rem;
}

.montage-product-thumb {
  min-width: 0;
  padding: .3rem;
  border: 1px solid #e4e9f0;
  border-radius: .55rem;
  background: #fff;
  color: #223454;
  cursor: pointer;
  display: grid;
  gap: .25rem;
}

.montage-product-thumb.is-selected {
  border-color: #f97316;
  box-shadow: inset 0 0 0 1px #f97316;
  background: #fff7ed;
}

.montage-product-thumb-image {
  height: 4rem;
  border-radius: .38rem;
  background: #f8fafc;
  overflow: hidden;
  display: grid;
  place-items: center;
  color: #f97316;
  font-weight: 950;
}

.montage-product-thumb-image img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.montage-product-thumb-name {
  min-width: 0;
  min-height: 2.2em;
  overflow: hidden;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  font-size: .61rem;
  line-height: 1.1;
  font-weight: 850;
}

.public-montage-preview {
  overflow: hidden;
}

.montage-preview-header {
  min-height: 4.1rem;
  padding: .8rem .9rem;
  border-bottom: 1px solid #e8edf4;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .8rem;
}

.montage-preview-header > div:first-child {
  display: grid;
  gap: .1rem;
}

.montage-view-tabs {
  padding: .2rem;
  border-radius: .55rem;
  background: #f1f5f9;
  display: flex;
  gap: .15rem;
}

.montage-view-tabs button {
  border: 0;
  border-radius: .4rem;
  background: transparent;
  min-height: 2rem;
  padding: 0 .65rem;
  color: #66758d;
  font: inherit;
  font-size: .68rem;
  font-weight: 900;
  cursor: pointer;
}

.montage-view-tabs button.is-active {
  background: #fff;
  color: #e65300;
  box-shadow: 0 .15rem .45rem rgba(15,23,42,.1);
}

.montage-scene {
  position: relative;
  min-height: 34rem;
  overflow: hidden;
  background: #e8ded3;
}

.montage-scene--main {
  background:
    radial-gradient(circle at 50% 18%, rgba(255,244,219,.95), transparent 18rem),
    linear-gradient(180deg, #d7c7b7 0 55%, #a47e58 55% 100%);
}

.montage-room-backdrop {
  position: absolute;
  inset: 0 0 45% 0;
  background:
    radial-gradient(circle at 20% 30%, rgba(255,255,255,.8) 0 .08rem, transparent .12rem) 0 0 / 2.2rem 2.2rem,
    linear-gradient(90deg, transparent, rgba(255,255,255,.45), transparent);
  opacity: .7;
}

.montage-table {
  position: absolute;
  overflow: hidden;
  background: linear-gradient(135deg, #f5eee7, #e5d3c2);
  box-shadow: 0 1.3rem 2rem rgba(49,35,25,.28);
}

.montage-table--main {
  width: min(72%, 40rem);
  height: 15rem;
  left: 50%;
  top: 47%;
  transform: translate(-50%,-50%);
  border-radius: 50%;
  perspective: 900px;
}

.montage-table--main.montage-table--rect {
  border-radius: 3rem;
  width: min(78%, 44rem);
  height: 13rem;
}

.montage-table--main.montage-table--square { border-radius: 2.2rem; width: min(62%, 34rem); }

.montage-texture {
  position: absolute;
  pointer-events: none;
  user-select: none;
}

.montage-texture--mantel {
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: .72;
  mix-blend-mode: multiply;
}

.montage-texture--runner {
  left: 50%;
  top: -8%;
  width: 24%;
  height: 116%;
  transform: translateX(-50%);
  object-fit: cover;
  opacity: .8;
  border-radius: 3rem;
}

.montage-main-place,
.montage-top-place {
  position: absolute;
  width: 5.5rem;
  height: 5.5rem;
  border-radius: 50%;
  display: grid;
  place-items: center;
}

.montage-main-place-1 { left: 9%; top: 28%; }
.montage-main-place-2 { left: 28%; top: 9%; }
.montage-main-place-3 { right: 28%; top: 9%; }
.montage-main-place-4 { right: 9%; top: 28%; }
.montage-main-place-5 { right: 25%; bottom: 1%; }
.montage-main-place-6 { left: 25%; bottom: 1%; }

.montage-mini-plaquet,
.montage-place-plaquet {
  width: 100%;
  height: 100%;
  object-fit: contain;
  filter: drop-shadow(0 .25rem .25rem rgba(0,0,0,.18));
}

.montage-mini-servilleta {
  position: absolute;
  width: 2.5rem;
  height: 2.5rem;
  object-fit: contain;
  transform: rotate(-12deg);
  filter: drop-shadow(0 .15rem .2rem rgba(0,0,0,.18));
}

.montage-fallback-plate {
  width: 86%;
  height: 86%;
  border-radius: 50%;
  border: .3rem solid rgba(188,144,67,.7);
  background: #fff;
  box-shadow: 0 .15rem .3rem rgba(0,0,0,.16);
}

.montage-centerpiece {
  position: absolute;
  left: 50%;
  top: 48%;
  width: 8rem;
  height: 8rem;
  transform: translate(-50%,-50%);
  object-fit: contain;
  filter: drop-shadow(0 .45rem .45rem rgba(0,0,0,.24));
  z-index: 4;
}

.montage-chairs-ring {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.montage-chair {
  position: absolute;
  width: 8.4rem;
  height: 11rem;
  display: grid;
  place-items: center;
}

.montage-chair-1 { left: 9%; top: 32%; transform: rotate(-8deg); }
.montage-chair-2 { left: 25%; bottom: -1rem; }
.montage-chair-3 { right: 25%; bottom: -1rem; }
.montage-chair-4 { right: 9%; top: 32%; transform: rotate(8deg); }
.montage-chair-5 { left: 28%; top: 4%; transform: scale(.75); opacity: .88; }
.montage-chair-6 { right: 28%; top: 4%; transform: scale(.75); opacity: .88; }

.montage-chair-base,
.montage-chair-cover,
.montage-chair-cushion,
.montage-place-chair-base,
.montage-place-chair-cover,
.montage-place-chair-cushion {
  position: absolute;
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  filter: drop-shadow(0 .45rem .45rem rgba(0,0,0,.2));
}

.montage-chair-cover { width: 82%; height: 82%; opacity: .8; mix-blend-mode: multiply; }
.montage-chair-cushion { width: 48%; height: 36%; bottom: 11%; }

.montage-scene-note {
  position: absolute;
  right: .8rem;
  bottom: .8rem;
  padding: .38rem .6rem;
  border-radius: 999px;
  background: rgba(12,24,43,.72);
  color: #fff;
  font-size: .65rem;
  font-weight: 850;
  backdrop-filter: blur(8px);
}

.montage-scene--top {
  min-height: 34rem;
  background:
    linear-gradient(rgba(255,255,255,.35), rgba(255,255,255,.35)),
    repeating-linear-gradient(90deg, #b27c4f 0 5rem, #a96f42 5rem 5.1rem);
}

.montage-table--top {
  width: 27rem;
  height: 27rem;
  left: 50%;
  top: 50%;
  transform: translate(-50%,-50%);
  border-radius: 50%;
}

.montage-table--top.montage-table--rect { width: 37rem; height: 21rem; border-radius: 4rem; }
.montage-table--top.montage-table--square { width: 27rem; height: 27rem; border-radius: 3rem; }

.montage-pos-1 { left: 40%; top: 2%; }
.montage-pos-2 { right: 4%; top: 20%; }
.montage-pos-3 { right: 4%; bottom: 20%; }
.montage-pos-4 { left: 40%; bottom: 2%; }
.montage-pos-5 { left: 4%; bottom: 20%; }
.montage-pos-6 { left: 4%; top: 20%; }
.montage-pos-7 { left: 19%; top: 5%; }
.montage-pos-8 { right: 19%; bottom: 5%; }

.montage-top-place { width: 4rem; height: 4rem; }

.montage-scene--place {
  min-height: 34rem;
  display: grid;
  grid-template-columns: minmax(0,1.35fr) minmax(15rem,.65fr);
  align-items: stretch;
  background: linear-gradient(135deg,#e7ddd2,#cdb59e);
}

.montage-place-surface {
  position: relative;
  overflow: hidden;
  background: #eee3d7;
  display: grid;
  place-items: center;
}

.montage-place-setting {
  position: relative;
  width: 18rem;
  height: 18rem;
  display: grid;
  place-items: center;
}

.montage-place-plaquet { position: absolute; inset: 0; }
.montage-place-setting .montage-fallback-plate { width: 80%; height: 80%; }
.montage-place-servilleta {
  position: absolute;
  width: 8rem;
  height: 8rem;
  object-fit: contain;
  transform: rotate(-10deg);
  filter: drop-shadow(0 .35rem .35rem rgba(0,0,0,.2));
}

.montage-place-chair {
  position: relative;
  display: grid;
  place-items: center;
  background: linear-gradient(180deg,#f8f5ef,#d8c6b2);
}

.montage-place-chair-base { width: 74%; height: 80%; }
.montage-place-chair-cover { width: 62%; height: 70%; opacity: .82; mix-blend-mode: multiply; }
.montage-place-chair-cushion { width: 35%; height: 25%; bottom: 22%; }

.montage-preview-foot {
  min-height: 3.2rem;
  padding: .65rem .8rem;
  border-top: 1px solid #e8edf4;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .8rem;
  color: #718096;
  font-size: .68rem;
}

.montage-preview-foot button {
  border: 0;
  background: transparent;
  color: #e65300;
  font: inherit;
  font-weight: 950;
  cursor: pointer;
}

.public-montage-summary-panel {
  padding: 1rem;
  position: sticky;
  top: 1rem;
  display: grid;
  gap: .8rem;
}

.public-montage-summary-panel header {
  display: grid;
  gap: .15rem;
  padding-bottom: .7rem;
  border-bottom: 1px solid #e8edf4;
}

.montage-summary-list {
  display: grid;
  gap: .45rem;
}

.montage-summary-list > div {
  min-width: 0;
  padding: .45rem;
  border: 1px solid #edf1f6;
  border-radius: .55rem;
  display: grid;
  grid-template-columns: 3rem minmax(0,1fr) auto;
  gap: .5rem;
  align-items: center;
}

.montage-summary-image {
  width: 3rem;
  height: 3rem;
  border-radius: .42rem;
  background: #f8fafc;
  overflow: hidden;
  display: grid;
  place-items: center;
  color: #f97316;
  font-size: .65rem;
  font-weight: 950;
}

.montage-summary-image img { width: 100%; height: 100%; object-fit: contain; }
.montage-summary-list p { margin: 0; min-width: 0; display: grid; gap: .08rem; }
.montage-summary-list p small { color: #f97316; font-weight: 900; }
.montage-summary-list p strong { color: #142845; font-size: .72rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.montage-summary-list p em { color: #8792a4; font-size: .62rem; font-style: normal; }
.montage-summary-list b { color: #132743; font-size: .74rem; }
.montage-empty-summary { color: #8a96a8; font-size: .75rem; }

.montage-estimate {
  padding: .8rem;
  border-radius: .65rem;
  background: #f8fafc;
  border: 1px solid #e5eaf1;
  display: grid;
  gap: .15rem;
}

.montage-estimate span { color: #68768c; font-size: .68rem; font-weight: 900; text-transform: uppercase; }
.montage-estimate strong { color: #0f2749; font-size: 1.45rem; }
.montage-estimate small { color: #8792a4; line-height: 1.35; }

.montage-secondary-action,
.montage-primary-action {
  width: 100%;
  min-height: 2.85rem;
  border-radius: .55rem;
  font: inherit;
  font-weight: 950;
  cursor: pointer;
}

.montage-secondary-action {
  border: 1px solid #d9e0e9;
  background: #fff;
  color: #243754;
}

.montage-primary-action {
  border: 0;
  background: #e65300;
  color: #fff;
  box-shadow: 0 .7rem 1.4rem rgba(230,83,0,.22);
}

.montage-primary-action:disabled { opacity: .45; cursor: not-allowed; }
.montage-saved-note { color: #16a34a; text-align: center; font-weight: 800; }

@media (max-width: 1320px) {
  .public-montage-workspace {
    grid-template-columns: minmax(18rem, 22rem) minmax(32rem, 1fr);
  }
  .public-montage-summary-panel {
    position: static;
    grid-column: 1 / -1;
    grid-template-columns: minmax(0,1fr) minmax(16rem,22rem);
  }
  .public-montage-summary-panel header,
  .montage-summary-list { grid-column: 1; }
  .montage-estimate,
  .montage-secondary-action,
  .montage-saved-note,
  .montage-primary-action { grid-column: 2; }
}

@media (max-width: 980px) {
  .public-montage-hero { align-items: start; flex-direction: column; }
  .public-montage-hero-actions { justify-items: start; }
  .public-montage-workspace { grid-template-columns: 1fr; }
  .public-montage-summary-panel { grid-column: auto; display: grid; grid-template-columns: 1fr; }
  .public-montage-summary-panel header,
  .montage-summary-list,
  .montage-estimate,
  .montage-secondary-action,
  .montage-saved-note,
  .montage-primary-action { grid-column: auto; }
}

@media (max-width: 640px) {
  .public-montage-page { padding-inline: .6rem; }
  .montage-preview-header { align-items: stretch; flex-direction: column; }
  .montage-view-tabs { display: grid; grid-template-columns: repeat(3,1fr); }
  .montage-scene { min-height: 26rem; }
  .montage-scene--place { grid-template-columns: 1fr; }
  .montage-place-chair { min-height: 14rem; }
  .montage-product-strip { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .montage-table--top { width: 21rem; height: 21rem; }
  .montage-table--top.montage-table--rect { width: 23rem; height: 16rem; }
  .montage-main-place { width: 4.4rem; height: 4.4rem; }
  .montage-chair { width: 6.3rem; height: 8.5rem; }
}
